    (89, "Sublime e Grande Amor", "acusação bebeu causa cegueira chora chorou começar conta dizendo estarás falando fazes grande gravar houve inda inimigos judeu malfeitor paixão paraíso perdoa proclamado profetas própria querendo rude satisfazendo sentiu sofrimento sublime suportando testemunho tivesse"),
    (90, "Há Paz e Alegria", "alegria amou conduz consolador céus dai derramou descer desfruto eficaz entoam espero filhos firmado gozo grande instruidor junto louvores lugar neste nuvens promessa prometeu prometido pátria receber reino remidos salvos sangue veraz"),
    (91, "Nívea Luz", "aberta acode almejo altar bom chamas colocar criar entrego espero fonte humilde instante instância lava lidar linda mão neste nívea pedem perfeito presença pureza pus quebro roguei sangue toma tudo ídolos"),
    (92, "O Bondoso Salvador", "alegre bom bondoso carregou castigo chamou conduz crimes cumpriu encarnou igual lenho livra livrou morte nome pecados perdoou publicar redentor remiu rude sangue sofrer trabalhar vinha"),
    (93, "Há Trabalho Pronto", "alegremente altos ama aprovação certo chama consolação contemplado crente cristão demanda devoção entender esforço feito fielmente for humilde los mestre obedecer perdidos plena poderás precisam preparou prontamente pronto quantos resgatou servi tiver trabalhar trabalho"),
    (94, "Na Jerusalém de Deus", "adeus alegraremos alegria brevemente caminho cantando chegar contemplaremos contemplarmos desta deste encontrar estender extenso findar gozaremos guiar hosanas iremos jerusálem luta mansão olhando passar perfeita perfeito provações pátria sairmos salvos sigo trabalhosa trono unidos"),
    (95, "Ouve, ó Pecador", "aceita aceitação amigos atenção condenação crer dai deixa digna enganador hesitação livre medita meiga mensagem ouve ouvi pecador perdão presta salvação temor tenhais terá terás trouxe vier voz"),
    (96, "Deixa Penetrar a Luz", "afastar alegre claridade combater consolador deixa enfrenta estamos feliz fervor fores formosa fraca fruto fulgure inimigo limpa mansão mostras nenhum par penetrando penetrar resplendor sangue serás temes traz trevas vivemos viverás"),
    (97, "Há um Caminho Santo", "além alívio amado caminho certo comprou conduz consolação dom escuridão escuro espinhoso fim for glorioso guarda inabalável incomparável minh nívea pecador plena preço sara satisfaz tirado triste verei veste vezes véu"),
    (98, "Estarás Vigiando?", "ansioso brado brilhará cheio culto darás esperando esperançoso esperas estarás glorioso gozo jubiloso noite ouvirás parte preparar pronto solene sorrindo sublime triste vier vigiando vindo"),
    (99, "Eis o Dia a Declinar", "adore bondoso contigo convida céus declinar dia enfim escuridão estrelas fazes filhos glorioso grande infinito insigne justiça louvar louve mar meditar mão ouve passar perdão perfeição petição plena profunda proteger seguros tudo"),
    (100, "O Bom Consolador", "aflição antros anunciai aprisionou bom brilhou celestial consolador cristãos derramar desceu dissipar dizei dom dor enfim fiéis gozo grande horror ide mandou misérias mora nova proclamar prometeu salvação sombras tentador terror traz veio"),
    (101, "A Unção Real", "bom buscar consolador convida crentes deixou divinal encheu humilde hóspede mandou obtém orando oração pentecoste potente prometeu prostrados real receber recebes recebestes roguemos salvar unção usar viro órfãos"),
    (102, "Crê na Promessa", "alegria alto cheio conceder consolador crê céus dará flux irás pecados promessa purificar receber receberá salvar serás tudo vencer"),
    (103, "Caminhemos na Luz", "amado andar bendita caminhemos cercado chegarmos céus esplendor face flux gloriosa guiando lar lindo morreu passos podemos receber reflete santos virá"),
    (104, "Jesus Procura a Ovelha", "abraçar achou alegra aprisco busca casa cessar chover clamar correndo descer desgarrada desgarrou dulçor escuta escutar estais faça feridos gemer jubila montes ombro ovelha ovelhas parar pastor pedregais possa procura procurara tenebrosos traze vagar"),
    (105, "A Gloriosa Esperança", "abatido braço chegar cobrir concede confiança deixa desvalido esperança fará forte força fraco gloriosa gozar irás laços nada passo pecador perdido possuis primeiro quebro satisfaz segurança sentes sofrer sorte sustenta tornou vencedor vigor véu"),
    (106, "Viva Cristo", "ama andar canto condutor conforta contento crentes depois derrama eleita escudo eternal exorta faça firmeza fortemente ganhou gran morte perfeita perfeição prometida pura reluzir riqueza rocha santos sorte sustento tesouro verdade vitória viva viver"),
    (107, "Firme nas Promessas", "alegro assolar batalhar cantarei criador dia dispensação falhar fico fim firme hei liberdade ligado louvores plena promessas purificação sangue tempestades verbo vivo"),
    (108, "Pelejar Por Jesus", "andar anunciei avancemos caminho combatei confiando contra crentes enfim escritura evangelho general gozar inimigo iremos leva lutai lutar lutemos olhai pelejar porvir prosseguindo seguir temer vencer veraz"),
    (109, "Venha a Jesus", "abraçará alguém braços chama conduz deseja estende fruirá gozará libertará morrerá mão pede perdão promessa pão receber santos água"),
    (110, "Clama: Jesus, Jesus!", "abraça aceita ama bom certo chora clama corrupção curar dará gozo guardar levar nome pecador perdão queres salvar salvação socorrerá terno terás tribulação vil"),
    (111, "Que Mudança!", "andava bom certeza cidade concedeu conta deu divinal entrando fez gozo guarda lavou morte mudança passar pecados penhor perdido salvou sangue selo temo transportar vale vindo"),
    (112, "O Nome Soberano", "advogado amado amável cima confio convém corpo criatura descendo deu doçura entregue escrito esperança exaltado grande humano intercessor maldito morte mão nome pões segurança sentado soberano terno vencedor verdadeiro vestiu único"),
    (113, "O Celeste Diretor", "andar atraído compraste confiando dia diretor dominador escondido fim fique fizeste for guiar instante inteiramente intimidade maior meigo morada morando passo pavilhão possível redentor salvação sangue secreto seja torne transforma unido verdade viver"),
    (114, "Aceita o Perdão de Jesus", "aceita aceite achar calmar cansado céus desejas desejos domar fonte limpa lutas morreu nova obter partir pecador pecar perdão podes pura queres quiseres santos temor tempo unir"),
    (115, "Trabalhai e Orai", "acharás conduzi confiando desejo dia escravos guia levando libertar los lugar obreiro ocupado orai orar palavra pecado quiseres seara trabalhai trabalhar valor vinha"),
    (116, "Livre Estou", "andar bom canto dada estou horror liberto libertou livre longe oprimido ouvi ouvir pastor pecado pensando segui seja senda temor terna vagava voz"),
    (117, "O Senhor Salva a Todo o Pecador", "amou cantaremos confio daqui exaltando falarei fervor jeová louvaremos pecador redenção rei sairmos salva salvação salvou sangue santidade tornar vencer verteu vivo"),
    (118, "Face a Face", "almas além breve cessar dia dor espero existir face glorioso gozarmos gozo hei houver mirar mostrar perigo plena pleno possa presença quanto quão redimir rosto veio vendo verá"),
    (119, "Inesgotável é Seu Amor", "bendirás bom chama chamar confiar creres deixa deixou divinal espera fonte gozar inesgotável irás livrar livre louvado momento nome obterás ouve pecado pecador perdão preciosa preparado queres salvar seja subir tardar terno trevas vivendo"),
    (120, "Noite de Paz", "astro astros bela belo bom brilha cantam celestes coros derredor dorme espargem estrela fiel fulgor indicando meigo menino nesta noite ouve paira pastor presépio redentor resplendor rosto sublime traz tudo"),
    (121, "Maravilhoso é Jesus", "abundante achou amou arrependido bastante caminhando conduz dum eternamente glorioso gozo grande louvando maravilhoso mui perdido perdoando podia prazer receber salvando salvou sião trevas tudo vive"),
    (122, "Fogo Divino", "alto arde calor celestial chama clamamos consolador consome desce despertar enche fogo fulgor inflamar minh mostra peito pentecostal restos valor"),
    (123, "Cristo Voltará", "afirmam alegre ascender breve comparação consolador devem dia dizemos encontro fim fiéis gloriosa grande mensageiros modo mui multidão ora promessas prometeu rei revelará sejas subiremos subiu terá valor velando verá vindo virá voltar voltará"),
    (124, "Adoração", "adorai adoração aumentei cedros centos contemplais dizeis dominador elevadas estelares gigante grama grandes gratos jovens louve louvemos majestade meninos mostrai pequeninos poderosos rendei revelai régio serras sinfonia submerso sábios trovoadas ventos verdejante vermes vitoriosos"),
    (125, "Quem Dera Hoje Vir!", "achar alvor arrebatados arrebatará breve começará coroar crentes dera deve entremez espera esposa fiei fim fora glórias gozo igual mortos multiplicados oração oriente prazer quele reinar santidade sinais subirão terminará trará velando vez virão"),
    (126, "Bem-Aventurança do Crente", "aventurado aventurança brisa começam confia crente creu daquela desalento desvanecem divisa esperanças fenecem fielmente fruíram herói heróis humilhação inteiramente levaram lindas melodias ouviram passará poesias queridos quiser santas saíram seio tribulação troféus via voa"),
    (127, "O Senhor da Ceifa Chama", "alcançar almas altar anunciando aproximando atendo brasa bênçãos ceifa chama chamando chorando considera depressa desfrutar espero expirando fala findos fogo leva mandar muitos participar procurar profeta queimando saudará servos toca torna trabalhos vindos útil"),
    (128, "Entrega o Teu Coração", "aceita aceitável acharia acharás adorável dia dinheiro direção entrega gozo libertado meigo mui nele perdida perdão queres ressuscitado salvação tempo triste vagas verdadeiro vero"),
    (129, "A Fonte Salvadora", "acharás alva arrependido contrito crer curado depressa despreza dor espera esperando fardo fonte humilhado instante manchada mercê mãos pecador perder pura purificar queiras receber salvadora salvar sepultá águas"),
    (130, "Cristo é Meu!", "amigo bons certo cheio consolador céus dando desfrutar dons firme forte grandes igual indigno leal mandou manso maravilhoso nada nega padeceu pastor perdoado puros ricos sondar tesouros tudo vasta viveu"),
    (131, "De Valor Em Valor", "aumentar avançar caminho conhecer daqui desejo entrarei esplendor eternal favor fiéis grande habitar junto leva livrar males manhã mansão minh mão prazer proteger queira receber ressuscitar sião suspira traz valor vejam"),
    (132, "Obreiros do Senhor", "alguns amoroso bandeira chamai colheita confiou dai derramou desprezeis devem enviou expirou falardes findará horas jaz levantai messe mãos novas obreiros obtereis passarão perdição poderá pregai prestes proclama segar trabalhar trabalhemos vacileis verão virão"),
    (133, "No Rol do livro", "achamos ajuda alegres altos andamos avante contentes criaturas céus desfrutar eleitos escrito escritos filhos fomos glórias gran herança inteiro levantemos livro marchemos nela nome nomes olhando olhos poderoso recebemos remidas rol sentindo servindo teremos"),
    (134, "Jesus à Porta do Coração", "abre achei bate batendo bater bom cear comoção decisão dentro duro enche entra escuto estou farei logo mansidão morar porta procurara queiras salvar sinto temer vale vim"),
    (135, "O Nome Precioso", "abençoada adoramos amado arca aumenta aviva bênçãos concedida confiança consolação dado enche esperança firme glorioso grande humilhamos nação nome oferecida pecador perdão pobre precioso predestinada prometidas pés quantas real sagrado santos verdadeira vigor vocação"),
    (136, "Jesus, Nosso Socorro", "clamamos combate conduz confiamos grande inimigo ofusca plena protege recorremos responde reveste socorro tentador tristeza valor vigor vil vitória"),
    (137, "Liberto da Escravidão", "abraão babel babilônia busca caldeus cantai cantavam coisas cruel disseram encheu entristeceu escravidão fez filhos grandes gratidão harpas hinos israel jubilar liberto libertos muitos ouviu pareceu prisão riso saiu sião sofrendo sonho volta voltarem"),
    (138, "Quem Bate é Jesus Cristo", "abre abrigo andas bate braços cear chegado conduz contigo deixar desejas deves entrar feridas for gotejar horror longe marcas mesa nenhum nenhuma perigo protetor recebe salvo segue sejas sofreu soluçar turbação vais volta vês"),
    (139, "Jesus, Meu Eterno Redentor", "abismo adão alegres amou buscamos carne consagrou consumou contente cruel dardo descido dessa emanuel entrou inferno libertar libertou maus medo ninguém obra paga podemos podia preparou rasgada redentor remido ressuscitar triunfou veremos vivo véu"),
    (140, "A Segurança do Crente", "admissão busca concedeu confundirá crente disse encherá enfim festa grande morrer mui nenhum perdão perturbação profunda proveniente puro quis real salvação segurança sinto temerei terei teres tribulação trouxe viva viver vivo"),
    (141, "Guia-me Sempre, Meu Senhor", "acho aonde compraste conduz descanso doce encheu escuridão ferida ficou gozo guia guiar jardim medo morto mão obedecer passos perto prazer rege reino reviveu seguir seguirei sentindo sentir sigo traz tudo velho"),
    (142, "A Cidade Celeste", "adoram adornada alguma alumiará arquiteto calçada cheia cidade composto consolará cortejo demonstras entraremos entrarão farão formosas gloriosas inscritos luzeiro majestosa modelo palácios pedras perpétuo planície posta praça preciosas rainha reinarão situada torres tratados vistas"),
    (143, "O Verdadeiro Amigo", "ajudar amigo andando ansioso avante bondoso cair certo confiar consolador contente defende desejo encontrar esperança fazendo grande guardes imensa levar orando perigo perseverança perto presença real redentor seguir sentir sião verdadeiro"),
    (144, "Vem à Assembléia de Deus", "alegria anulada assembléia caminho cantos certeza comigo consolador contigo convém deixa entoar estejas exultando fruir gozarmos humilde igreja imenso lindos louvemos maior ouvir palavra presença pés querido santidade santos sentença sentimos sentir terás trevas"),
    (145, "União do Crente Com Seu Senhor", "aflição almeja ama andar consolo crente desejo desfalece dor escuridão face fervor guias honrar incomparável leis louvar mão nome pensar perfeita preceitos procura pão recebe salvação satisfaz sedenta sofreste temor união veraz verdadeiro vives"),
    (146, "Caminho brilhante", "ama andar brilhante caminho canto contente encontro estou feliz fim guiará hei lembrar livrou majestosa morte nele ouviu passou perecer prazer purificado rei reis remiu separará sião trevas trilhou tudo vacilar venço"),
    (147, "Servir a Jesus", "alcançarei alegre bom caminhar comunhão confio contigo dando desça entendimento falarei fervor glorificarei muita nele pecados prazer purificação receber rei seguir servindo servir serviço sião tendo trabalhar venhas veraz vitória viver"),
    (148, "Bendirei a Jesus", "ampara bendirei cansados conduz coro coroa cuidados dele deu glorioso gozo guia leva louvarei louvo lábios nada pés rei salvação separa sublime sustenta sábio vitória"),
    (149, "Canto do Pescador", "acabando apanhando apraze barco canto coisa continuar crlsto deitado desanimarei devo ensinar envergonhou ganhei gastei lançarei levo menor modo novamente parar peixes pesca pescador pescar puxada receberem rede remar revés temporal tenha tio usa"),
    (150, "Para Casamentos", "aliança amado andarem bom casamento casamentos cheios concedendo confirma contentamento doutrina enchendo esperança estamos faze guardados guiados mandado mão noivos pedimos proteção união vinda viverem"),
    (151, "Fala Jesus Querido", "aberto alegremente amar antigo bondade consagrar fala fica filhos gloriar grei honrar lei livre louvar louvores mostra obedecendo ouvir pedir quererão querido revelaste servir som stá suavemente tempo terno tom vencedor vidas vontade voz"),
    (152, "Pela Cruz ao Céu Irei", "achará cairá calvário celestial deixou dor fanal fardo fonte gloriosa inspiração irei irá lar levando mansão marcado morrendo mortal obscura pare pesada rumo salvação sedenta seguirei transportou"),
    (153, "Soldados de Cristo", "acerca armas aurora avante buscai desmaio destra dizendo entrastes estejas faustoso frente galardão grandioso inimigo levai levando lida lutai marchei numa peleja perdidas prestes prossegue prêmio qualquer sair soldados terão triunfantes valente valor vencida"),
    (154, "Doce Nome de Jesus", "adoro belo bom cheia doce dor falta grata louvarei nele nome parte pesar proclamar puro põe rei salva salvarás tirar verdadeiro"),
    (155, "Imploramos Teu Poder", "aquece assoprar bendita brisa bênçãos comunhão contigo depressa derramar despertar dormem encher faze fogo frios fruir gozar imploramos inflamar limpar mancha outorgar paternal perene pleno proclamar promessa prometeste queiras renovador revestir suplicamos ungir óleo"),
    (156, "A Ovelha Perdida", "achei achou amante amou bom braços buscou cabal caído chagas comigo dele disse distante ferido guiará levou longe ovelha passos pastor pensou perdida prossigo protege querido rebanho redil restaurou salvadora seguiu senti singular ternura"),
    (157, "Cristo, em Breve, Vem!", "acordar alegria aprontar breve brilha clarear corações crista dalém demorais encontrar escravizados escuta estais forte fugir fugiu grito hão iremos mensagem nações noite nova ouvi povos preparei provém queiram rugindo soa traz tribos vendaval"),
    (158, "Que Farás de Jesus Cristo?", "aceito aflição alegre crlsto deixado dia diante diria dirás farei fará farás gratidão julgado julgamento mui multidão nazareno pergunta pilatos recebido repete responde stá"),
    (159, "Cantai, ó Peregrinos", "antes canseis cantai cantando cantei celestial continuamente coro crescendo divinal encontraremos esperam estais estareis glorioso harpas hino história junto lida louvai melhor monte nada passais peregrinos pátria reis responde sempiterno tocai transborda turbará velha"),
    (160, "Deus Nos Quis Salvar", "alegres avançar breve devemos encontrar fomos gloriosa louvemos mui olhando palavra precioso proclamar publicar quis repletos salvar sangue unidos veremos vertido"),
    (161, "Navegando Pra Terra Celeste", "alerta amigos andará barco bastante bodas convite deixar descanso entrarão festa fim findando fácil guiará irei jazes jubiloso lembrai louvares manhã mares morar naufragar navegando noite porto prometeu qualquer ras romperá saúdo tentador terras"),
    (162, "O Estandarte da Verdade", "arvoremos bênçãos consolação copiosas desperta dor encontrarás estandarte evangelho grande levantemos levemos luto mensagem nele ouve parte pecador proclamaremos proclamemos salvação soleníssima sono valor verdade"),
    (163, "Cristo Morreu Por Mim", "atroz calvário crendo cumpriu dor estou fez gloriosa horrenda morreu morte nesta obra ouvires pecado pecador penosa prazer raiar remirá revendo senda sofrer subiu tira voz"),
    (164, "Paz Luz e Amor", "abre abundante bom busca concedida consolador deixa deu gozo horror maia maravilhosa pecador perdão pobre queres recebe receber recebi salvação satisfaz sus terás veraz"),
    (165, "A Armadura Cristã", "armadura astuto atirar bom calçados cingidos combate coragem crista dardos entrai escudo evangelho ferventes furor inflamados inimigo justiça lombos porá procura pés repletos segura seres tentador tragar unidos valor vencedor vencerá verdadeira vestidos zelo"),
    (166, "Deixa Entrar o Rei da Glória", "abrigar aceitável ama amável chama deixa deste dia entrar entregar finda linda lugar morte mui ouves pecado pecador podes prazer rei ressuscitado salva salvar sedutor temor vires vista"),
    (167, "As Testemunhas de Jesus", "acharem acordaram aliviar amazonas anunciai boa buscam causa cheios companheiros cura demônios desconhecendo despertar enfermos entregaram escravo expulsos legou ociosos ousados parta pentecostal poucos preparando proclamai proclamamos publicamos reunir revelar semeia stão testemunha testemunhas"),
    (168, "Meus Irmãos, Nos Jubilemos", "adoremos alegramos amado aviva bom canto congregados consolador desfrutamos entoa entoemos fomos gerados gozo hinos jubilemos liberdade memória nesta pecado perfeito pranto recebemos rei resgatados salvação santos secar sermos vitória"),
    (169, "Oh! Jesus Me Ama", "ama andava caiu caminho cansado chama deseja desejava dor explicar fardo ficar fui horror juízo longe maravilhoso minh pecado pensava perdição perguntava pertencer pés queria repouso salvar salvação tristezas"),
    (170, "Ao Calvário de Horror", "aceitar achará calvário dissipou eternal gozo havia horror levando mandou maravilhoso mão pecador perdido raiará réu salvar salvou subiu trevas vindo"),
    (171, "Um Pecador Remido", "aceita amado andava ansioso braços breve clara concedeu conduz consigo consolador demorar descerá entrar esperança estou gozar guiado iluminar lavou levará morar ora palavra pecador perdão pobre queres raiar receber remido salvou tardança veio"),
    (172, "Ó Vem Te Entregar", "abatido aceita bondoso calma cansado carrega cheio comoção consolação contra crucificado crê desanimado domina entregar entregas espera grato morte neste paraíso país pecador queres receber revestido salvar salvação sentes terás vagas veio vicio vindo"),
    (173, "Os Santos Louvam Ao Senhor", "cantando certeza direito feliz firmes grande havemos indo lavou louvam louvar podemos promessas pronto quis redentor redenção resgatou salvar sangue santos sião stamos triunfar veio"),
    (174, "Glória, Aleluia, Gloria", "andar chegar estou gozo hei irei livrar livrou louvar salvar salvo salvou"),
    (175, "Irmãos Amados", "alegre amados avante canto combateremos estais fazendo fui lavado lavados libertados mui nome perdido prudentes purificados remido remidos resgatados santificado santificados sede segui temendo triunfantes unidos valentes venceremos vivei vivi"),
    (176, "Sacerdotes do Senhor", "achega alfa arrimo cantaremos cessar cheios contentes demos derramado emos entraremos esposo feito hinos honra inteiro jubilosos juntos mente novos perfeito primeiro regenera reino reis resgatou sacerdotes sangue suma tendo traspassado ultimo verdadeiros ômega"),
    (177, "Salvo Estou", "aceitação acheis alegria amado cantarei chegar comprou concede deu digna duma estou fim forte gloriosa harmonia jubiloso lida louvarei mensagem pecado perdição poderosa recebes redenção reino salvação salvo selou som spírito"),
    (178, "Gloriosa Paz", "alento açoitem braços conflitos crendo doce dores fará gloriosa grande inda inefável insondável mar minh obter perfeita repousar salvou tentador vencedor vim"),
    (179, "Redentor Formoso", "alvor anelo avança bela belo cumprido depois deste dia dum esperança estrela favor formoso gran habitas horror humilhado mente minh mão nascer noite olhos prazer pés redentor remido remirá retira sustente tiver verdadeira"),
    (180, "Em Cristo Fruímos a Paz", "achamos agradável aonde buscar cheio fim forças fruirmos fruímos gozo havemos imenso inexplicável podemos prazer renovar repousar sinto vigor vivas águas"),
    (181, "Vem, Celeste Redentor", "achei ajudar amado atrai buscou conheço contínuo derramou desgarrado devedor dignos entoar eternamente fonte fruirei hinos inferno ingrato momentos morreste morte pecado penosa perdão peço pobre receber redentor rege salvar sangue tira vil viver"),
    (182, "Jesus no Getsêmane", "abandonado arrastado atingido atormentado brado carregado clamava cometeu corte crucificado dias embalsamado enganado ensangüentado enterrado flagelado getsêmane guardado insultado lança ligado pecado perdoa ressuscitado sentença sepulcro sepultado tal tirado traspassado três turba vituperado ímpios"),
    (183, "Ressuscitou!", "abençoando aniquilou apresentou cogita convosco deixou destra discípulos disto esposa galiléia levantou nuvem ocultou ordenou parti pedi presos proclamou promessa reinará ressuscitou revelou riso saudou sentado sepultura seres suplicando tornou tremendo triunfante voltará voltou"),
    (184, "Meu Jesus! Meu Jesus!", "ação bendita cadeias cantarei chamou começo condição dai dando encontrei fartou galardão gratidão hinos hão imenso limpou livrou louvores mandou parar passados perdição pranto purificador remidor ruína salvou sofrer solitário terno tristeza vagar ímpio"),
    (185, "Invocação e Louvor", "abençoar afasta anjos chegar condutor consolador corações céus falar fervor fiéis glorioso grande guiar inspira invocação louvar louvem louvemos mensagem oração orações par plena prosperar reger rei reis salvação satanás traz trino verbo"),
    (186, "De Valor em Valor", "andar andarei armadura combate combati contra coragem cordeiro coroa dada dará destreza direi dura enviada farei findar hostes justiça liça lutar mil peleja proezas receba seguir tentador terei valor vencedor vestir vez vigor vil"),
    (187, "Mais Perto Meu Deus de Ti!", "alegrarei alçará andando betel braços cantará chamar céus descanso dor enfim hei inda irei minh morar padrão perto rei rogar seja serafins solidão sonhar suplicar trevas triste una vier"),
    (188, "O Gozo do Céu", "acordes buscar canaã celestes cima compreender confiar deixar entrar evangelho feliz gozar gozo lindos minh muitos negar ouvir possuir prazer recebi reinar segui spírito tomar transformado viver"),
    (189, "Glória ao Salvador", "aflito amou bom chegado clamor demorar inda junto laços livrou lugar maravilha ouviu perdoou pronto prostrado pés quebrou redentor salvar salvou tudo"),
    (190, "Cristo! Meu Cristo!", "advogado agrado amado amou cansado concederá defende desejo doce débil escuta face fez fim humilde morada morte nome pecado petição protetor quanto repousa salvou segura terno tranqüilo triste vigia"),
    (191, "O Meu Jesus", "achar amar angustia anjos anticristo arrebatar comparar conduz corpo encontrar enfim fabuloso fervente hino horrenda igualar intercessor introduz irão majestade mortais ninguém pagou pedindo poderei potente preço reinar ressuscitou senão sofreu suplantar tremenda voltar"),
    (192, "Pelo Sangue", "achei antes bom brilha calvário carmesim carregou compreendo cordeiro culpa divinal grande livrou manou morreu mui oferece padeceu pecador pecados pendurado perdição pregador redenção redimidos salvação sangue tal tema temor valor vivi"),
    (193, "A Alma Abatida", "abates abatida abençoa alegre altos breve calma cedo comoves confiando dores espera fica findas infalíveis intercede males medo minh nele perdendo pouquinho promessas recebes ricas salva suplicas tarda tenhas terás valer verás vinda virá"),
    (194, "Jesus Me Guiará", "amante compaixão concede constante contacto contrito célicas duma escarpadas explica ferida guiará horizontes infinita inquieto liberdade livra manchas montes moradas muita mão perene pisadas presença proteção purifica sendas sombra traçará vales velará vele verdade"),
    (195, "Benigno Salvador", "andar aprovação bendita benigno caminhem casa consagra consola corações cumprir descer descobrir digna dóceis juntos lei ligados livra los manter mister nesta noivos passar petição podemos reger salvos sombra tentação terno tribulação unidos união"),
    (196, "Uma Flor Gloriosa", "achada achei achou alturas beleza brilhar buscar confesso depressa deseja desta excelente flor gloriosa humildemente muitos odor ofertada paulo perdes perseguia preciosa precioso provado rosa saron saulo sombra sorte terá tirada transformado vale zeloso"),
    (197, "O Lar da Glória", "amigos anjos breve brilha cobertas conta depois dia encontrar espero feliz ficar havemos juntos lar levanta lugar mui olhos ouro pedras preciosas preparar reinar ruas sal seguirei voltar voltarei"),
    (198, "Jesus o Bom Amigo", "abandona abandonará amado amigo bom conserva deixei desampara dores entreguei escolhido estrela fortaleza guarda guarde levou lírio manhã mediador milhares muro mágoas obediente persiga protegerá protetor purifica queimei solicitude tentação toma vales voando ídolos"),
    (199, "A Ceia do Senhor", "beber buscar ceia comunhão corpo cálice devemos dignos divinal esquecer fim lembramos lembrar morte partindo purificador pão reunidos salvação sangue símbolo venhas veraz"),
    (200, "O Bondoso Amigo", "alcançar amigo amigos bondoso carregado carregou consigo conta cuidados culpado derramou desprezam disto dorido encarnou expor falta fraco futuro lavar levamos levemos mancha manda mostrou nei oração podemos provas puro quão refúgio terno verdadeiro"),
    (201, "A Decisão", "abracei afirmarei alegre além atração cedi chamou completa confiante céus decisão descansa deste dia ensina excelso exultarei feliz imensa nele orar possui publicarei pão resiste sacro satisfiz sustento súdito tentador transação vigiar voto voz"),
    (202, "Lugar de Delícias", "acabam acodem cansa concorrem conosco conservemos dali delicias desse encantos esfera eternas exaltado existência guardemos idéia junto lembrança lugar oferecer país pedir perfumes perpétua prazeres profusas protetor quisermos rodeado ternura tornar ventura venturas verdadeira"),
    (203, "Deixai as Ilusões", "acompanhar alguns amigo andar avançar breve deixai deixei descansar deseja dor entrar gloriosa glorioso gozo hei ilusão ilusões impedir lar livrar pecado procuram queres senda"),
    (204, "O Peregrino da Terra", "anelante anjos brandamente buscar celestial coro coroado crente crido descansar descansarei descrença dores espera fonte guiando hei longe louvado lutas mlnh morar num peregrino permanente presença prometido sofra tendo terá trono vezes viva viverei"),
    (205, "Graça, Graça", "achei alta basta bens celestes choro correndo dada daqui doce fartar favor fizeste fonte funda gozo infinito limpa mar nuvens perdido perdição podemos profundo prova renova revelada salva terrestres tornou vives"),
    (206, "O Clarim nos Alerta", "alerta anjos bodas cantaremos canto cearemos certa certo clarim coberto coroado crente desperta felizes fruiremos gozaremos júbilo liberto mesa mil ouviremos pranto prazenteiros preparado quão reinaremos rodeado salvo sentaremos seremos verdadeiro veremos vinda volta"),
    (207, "Jerusalém Divina", "altares amemos andamos celestiais cingem cristalinas ditosa doze entoam escritos fontes fruiremos gozos imolou imortais jerusálem livros milhares moradores nomes ouvidos passados perdoou preparados proferem prontos radiante redor seres temamos transpostas umbrais visão vivos"),
    (208, "Vem a Cristo", "achar cansado celestial chama crendo culpa derramado desfrutar dia divinal dor encontra ensina entregar gozar grande gólgota liberdade meigo nazareno obter padecendo pecador podes queres receber renunciar resplendor rochedo salva santidade terreno triste visto"),
    (209, "A Voz do Bom Pastor", "abrigar ajudar aprisco bom bondoso cercado chama cordeiro densa dentro deserto devorar enganador escuridão escuta espalhar esplendorosa evangelho foge lobo mil pastor pecadores perigos proclamar procurar receber redil solidão temor triste vaga voz"),
    (210, "Fala, fala, Senhor", "alegria ansioso conduzem conselhos conservo escutar estou eternal fala falar falas fervor hora mui nesta nome ouvir ouço palavras porvir pronto repouso restaura ricos saúde seguir superno sábio valor veredas vigor zelo"),
    (211, "Vem a Deus", "andando braços chama confiando crê demores derrama entregar espera fardo feliz neste pecador perfeita quisera receber salvar salvará salvação sejas sentes serás tardo terás tranqüilidade triste vais volta"),
    (212, "Os Guerreiros Se Preparam", "alcançará alegrando atacam batalhar batalhões belial certa combatem coroar dormindo furioso guerreiros impoluta imprevisto inflama lance luta marcha milícia oprimidas peleja pobres poucos preparam pressa prosseguindo renhida tragar travar tremenda vacilante vaciles vires vês"),
    (213, "Sobre a Terra Vou Andando", "acabaram agonias amável andando angústias bondoso buscando cessarão comigo conservo coragem ferozes guiado incomparável inimigos lutas males nessa pastor pelejando perene perigos persevero prantos prestes pátria raia salmodiando satisfeito segura tornar trabalhando vales viagem"),
    (214, "Desejamos ir Lá", "alegria brevemente casa chamará cordeiro descansar desejamos encontrarmos enganador esplendor havemos hinos iremos lar lugar nesta neste novos possam preparar redentor reinar repouso salvar salvos segurar tesouros veio"),
    (215, "Ver-nos-emos", "amados andar anelando anjos ares breve contemplar dia divinal emos enterram esperam esteja frente havemos hão igreja igual junto lar milhares morrer nada neste olhamos peregrina permanente rei remidos rio terminar tudo verdadeiro verá"),
    (216, "Louvai a Deus", "adorai alegres anunciai bens cantando cantaremos celebrando céus daremos demos devemos falar fama força glórias grande graças guia habita juntos júbilo louvai louvei mil multidão mão onipotente presente prodígios publicai redentor salvação seguros sempiterno"),
    (217, "Ouve Sua Voz", "amarguras amorosa atroz breve caminho carregares chama chamar ditosa dor encontrar fala fim irás levar libertar mau morte mui mão ouve ouças perante persiste piedade poderosa procuras sofrerás torna voltar voz"),
    (218, "Dá Teu Fardo a Jesus", "abrigo achar assaltam cansado descansar dissipar dor fardo fará fruir fugir gozo grandes inquietudes libertará lutas males mil pecador penas perigo podes queiras queres redentora santos socorro temor terá terás trevas vais vigor virá"),
    (219, "O Amor do Criador", "altos amava brilharam compreendo conduz criador criação dantes darei derramaste deserto desta dias dom enche expirou fui inesgotável insondável liberto lugar medirá perfeita plagas precioso preparava provendo quanto raios revelaste revelou salva salvou trevas"),
    (220, "Ide Segar", "anunciar campos ceifar chegará clarim demorar dia falai falar falaremos fervor fim galardão ide impele labor lourejar mandar mar monte perdidos pregar proclamai proclamar procurar pronto salvar segar soará sofredor tereis trabalhai trigo vale"),
    (221, "Opera em Mim", "ardor bom clamor consolador cumprir dura escuta espero favor fruir gozo guarda lei morte opera par perfeição peço podes pés revela sangue sedento tardes valor vertido vigor"),
    (222, "Vem a Jesus, ó Perdido", "abertas além anjos assertos cessa crê demora demoras depressa enganar entrada espera estará estarão finda guiar horas libertos parte passam perder perdido portas salva sangue sofrer terás triste tudo vertido"),
    (223, "Na Minh’Alma Reina a Paz", "alto auxílio avistei cercado chamou clama dor eficaz encontrares escuridão fui furacão gozo grande grandes guiar mar mil minh mui ondas pelejar penas perdição piloto pudesse reina tardar veraz vim"),
    (224, "É o Tempo de Segar", "aguardando alerta brancos brevemente brilharão campos colheita darão declaraste desperta entra findará gavelas jovem jóias madura obedece olha passando perante poucos premiador pronto recolhes responder restam seara segador segar segarão tempo trabalhar vacilar vazio"),
    (225, "Sê Valente", "altruísmo alvo batalha brasil caídos cheio contra deixes enfrentar enobrecer escudado firme for franco indômito lutarás maligno manifesta marcha mostrarás olha pelejando proclamar recuar redor rejeitando segue serás temer triunfal valente valor vencedor vencer"),
    (226, "Cristo, Teu Santo Amor", "alegre almas conduzir contigo cumpro deste espalhando estarei estou favor gratidão guia hei hino igual junto levar mão nada negarei nome pede perante proclamar prontidão prostro redimir rendo rosto servir tempo trono verei viverei"),
    (227, "Deus Amou de Tal Maneira", "abraçar além amado amou coroado coroe crê desviado enviado espera esperança gozar humanidade inteira justiça liberdade maneira ouve pecado pele perece permanece podes prisioneiro receberás sofredor tal trazer vagas vencer vencido vestido vives voz"),
    (228, "Este Mundo Não Compreende", "aflição alegre atende chegado compreende céus dia ditoso estou for glorioso gozo guardar hei maior morar mui provém pátria quão sinto transformado traz viver"),
    (229, "Jesus, ó Meigo Salvador", "abriu braços conduz conduzindo deleita desejo dulçor encontraste enfim entraste exortes fiel fundas guardarás levaste livraste logo meigo miserável morte mui mão oriundas palavra perfeita porta profundas pés rocha seguindo sorte trono vindo águas"),
    (230, "Nós Vogamos Nesta Nau", "abrirá amamos amigo ancorar bondade chamada chegados cheio cidade conduz cujo findar havemos hora leme morada nau naufrágio nesta olhamos partir porto presteza rumamos saltar seguir sorrirá tardar tememos tormenta travessia vemos vencemos vogamos"),
    (231, "Não Foi Com Ouro", "abismo abre caminhemos comprou concede criador deixa eternal guarda guia horror morte nenhum ouro preparar real recebemos repouso salvar salvação salvos sangue seguiremos temer temor valor vencer vertido"),
    (232, "Os Bem Aventurados", "alegres anelo aventurados buscam caminhar cheio concede dele demos desfrutam discriminadas dita encher eternamente favor gozarei imenso jubilosos limpo louva obedecer perfeita pobre poderão possuo prazer quão riquezas tornará tranqüilidade veraz verdadeiro verteu véu"),
    (233, "A Ceia Do Senhor", "abençoados alegra aleluias alimentarmos amado cantaremos ceia consagrados consolador céus dado dia enchendo estamos grande hino lar lugar morte provar pão quiseste relembrarmos reunirmos salvos sejam sejamos unidos vinho"),
    (234, "O Gozo Dos Santos", "aberto aflição coberto confiando coroa cravos cruel cumprida dor emanuel enorme estampa face ferido fonte furados gozo lado lança lenho mãos obra padece possui potente pregado produz pés sai sangue santos spinhos vertido água"),
    (235, "Já Sei, Já Sei", "alegre beleza calar comprado consolar contemplar coroa dará deixar deveras dia enchendo espera espero estou falar favores fortaleza gozo grande lei liberto livre maldito minh pessoa porvir quis redimir rei sangue servos severa vicio"),
    (236, "Já Nos Lavou", "comprou cordeiro crerdes crermos derramado desfrutar dons dura entrada feitos fomos imenso imortal indica infinito lavado lavou libertou livre madeiro oferecerdes precioso predestinados provou purifica reis resgatado sacerdotes sangue santificado selados sereis tentador vil"),
    (237, "O Gozo de Estar Preparado", "breve coroa desfazer desfrutar divinal encontrar esperar estamos gloriosa gozo luzes noivo preparado prontos redentor rompendo servos sião tardará teremos virá viver voltará véu"),
    (238, "Ó Pecador Desalentado", "aceitar aprazível atribulado braços chamando convidando desalentado desprezes dia fortaleza grande horas horror irresistível lançando liberdade morrerás nele neste passa passando pecador queres recebe rejeites repouso santidade senão terás tristeza tudo verá viver voz"),
    (239, "Imploramos o Consolador", "amado benigno bom caro completa consolador dileta enchendo espero fora glorioso imenso implora imploramos manda minh obra pertence redentor sedutor selar tempo tirado torna vitória"),
    (240, "Oh Dia Alegre", "alegre alegrei além amigos ansioso breve buscar cantando céus dera descer dia estou fiel fim for haverá irei lar livre margem ouvir parece partir salvos temporal terá tudo vinda virá"),
    (241, "Marchemos Sem Temor", "algum bom caminhamos carregando chamamos daqui depressa desanimar desejamos dirigidos entrar errar estamos filhos marchamos marchemos olhar pisadas podemos presto proclamar rasga redentor repletos sião tardar temor triunfar trás valor vendo verdade véu"),
    (242, "Eu Confio Firmemente", "adorar alcançar alegremente alegria assentado canto chegado comprou confio contemplar cordeiro descansar desfrutar expirar fez firmemente for gozar hei herdeiro lado madeiro murchar pendurado pensar pranto prazer quis rosto salvou sente soar sublime trono"),
    (243, "Ao Abrir o Culto", "abençoa abrigados abrimos abrir adulto amados ave cordeirinhos culto dado desejamos doçura enlaces enxuga face família filhos fogo gozaremos igreja lavra manda moribundos ninho nova peito pequeno pranto pureza ressuscitadol servos suplicamos tardes vejas"),
    (244, "Louvai a Jesus", "amoroso cativo confia consolação dai deu enche ganhou gozo guia levou livrar louvai medroso pecados poderoso prisão proteção real rei salvação sangue temor tribulação veio vencei vitória"),
    (245, "Paz de Deus em Jesus Encontrei", "alcancei baixou consolador desfruto deu dom encontrei enfim expirou gozo honra real redentor repleta salvar salvação sangue tributarei trouxe verteu"),
    (246, "O Descanso em Jesus", "acharás aprender chegar concedeu consolação corajoso descanso deu encontrado encontrarás estarás hás irá manso mirar ninguém oração permaneces plena plenitude provações santos seguro tentação terríveis tirar vitorioso vitória"),
    (247, "Deus Nos Guarde No Seu Amor", "achemos agruras breve carecemos conceda coroa eternal formar guarde jornada livres louvaremos mansão mui nome qualquer santificação separação terminada vivemos voltar"),
    (248, "Hosana e Glória", "aldeia avistando betfagé calar calarem clamarão clamor concedendo davam dizei eficaz enfeitou exulta filha hosana ide jumentinho louvam mandam monte montou multidão ninguém oliveiras ordenou ouviu pedras perguntem ramos requisitou temas trazei trazendo trouxeram"),
    (249, "Ó vem, Senhor, e Habita", "batiza batizar bendita compaixão consolador desfrutar dia dom dor enchendo falarei glorioso gozo habita hora louvarei minh nesta ouve peço pranto puro selar"),
    (250, "Noiva de Jesus, Apronta-te", "abrigado amado apronta bela bondade calma caminho cidade concedida desejo divinal enche ensina fruir igreja irás males mandamentos manifesta minh nele noiva protegido reinado remida rodeado seguir sustento terei unida unido vero verá vitória"),
    (251, "Ao Culto Não Faltar", "breve culto faltar falteis fervor levando louvar nome pecadores porvir pudermos reunir santos separamos trazei veremos"),
    (252, "Santo, Santo és Tu Senhor", "adorar anjos arcanjos avante buscar cantarei celestial comer confiarei consolar consolação deserto enche entrando esperança eternal faças fortalecer força hei levar mansão maná peço proclamarei pão queres querubins quão reino resgatou serafins sião vital"),
    (253, "Avante, ó Crentes", "afastaremos alcançar alcançaremos avante bom combate combateremos concedida corajosos crendo crentes desfazendo dum esperança firmaremos fiéis galardão inimigo marchai momento nele pecado peleja pensamento receberemos sede tarda tardança temendo valorosos venceremos vil vitória"),
    (254, "Mais Perto de Jesus", "alcançar alvo andar breve conhecer desejo dia divinal dor faça firmado fruto humilde importa inteiro mestre mostre perto profunda profundo viver vontade"),
    (255, "Meu Redentor", "apagar chama confia creres deseja detenhas egito entrar fará ferir finda fruirás juízo levou maldades malfeitor maravilha morrendo nele nova passará pecador pecados perdoou promete recebes redentor salvo serás sucedeu terás vais verteu vil"),
    (256, "Abandona Este Mundo de Horror", "abandona aceite amigo barco barra cansam castigo cessar clamar clarear duma escutas falta faróis foge horror levará mar marcar maré naufragar perigos persistes poderás podes proceloso quebrará rapidez salvará sustém tardar vagar vez vozes"),
    (257, "O Perdão Sem Igual", "amoroso cessar compaixão confessa contemplo contrito darei exaltar fonte grato igual intercedes meditar par pecar pede perdão perfeita quão real redentor salvação trono"),
    (258, "Na Rocha Eterna Firmado", "alegre ando anjos basta bênçãos cargas desfrutando deu entoarei esconde estou etão findando firmado hinos liberto lida manto meigo morreu mão pecados presto prossigo resgatou rocha salvou santos senda tive tomou velando verei vivo"),
    (259, "Creio eu na Bíblia", "acharão acho apagados buscam bênçãos bíblia caminho cantando cantos celestial creio divinal doce dom encontre ensina honrar lar lemos lindas livre livro maná melodias mostra par pecados pecar plena prometido redimido santidade sendo vitória"),
    (260, "Avante com o Nosso Capitão", "alcançai alegres avante avançai bíblia capitão comandante conservada contra dada deleitosos dissipai espada esperamos exultantes firmes goliá herança jugos libertou lugares lutareis pelejai pelejarmos penosos sagrada seremos sorte supremo temer tocou triunfantes vencer vitória"),
    (261, "Alma Triste, Abatida", "abatida acho adornou andas atua concedendo confiante constantemente dimana dores enches expiou expirou farol finda fortemente gratidão imensa jorrando livramento mares medo morrendo olha perecer pregados pura remiu seduziu segue sofrimento triste triz vacilante"),
    (262, "Senhor, Estás Comigo", "alimento buscando caminhando comigo contigo cumprir dia estamos evangelho face fazendo feliz guardando mandamento maná pecado proclamando resgatado santificados sofrimento sustento tempo vil vivificado"),
    (263, "Ao Fim do Culto", "bom certeza coisa consolador contemplarmos culto dia doutrina enche ensina fim gravar juntos perdoes perturbado qualquer queiras regressarmos santos suplicamos sustenta tendo terminado"),
    (264, "Ó Pai Celeste", "abrigados abundância brama braço cervo cheia chuvas defende derrama desejamos dirige dirigida firmeza fontes fortaleza mente pavor preside produz prontidão realizado rebanho recebido reverente saciar sacra seca sedentos sela selado transbordar unido viagem vivas"),
    (265, "Doce é Crer em Cristo", "andar ateu bonança busca confiar crer cumprir descrendo deste doce entregar esperar grato infinitos luta mui palavra perdão precioso promessas proteja quão tesouros"),
    (266, "Resgatados Fomos", "aceitos desfrutar eleitos fomos gozar havemos imortalidade liberdade livres louvar meio pecar quis recebido remidos resgatados salvar"),
    (267, "Jesus Minha Força", "alegre amado andar causando chegado chegando contente descansar desejo dia dor enchente encher errar ficar força grande guarda mão passos pecados perto potente predita seguindo temor terror tranqüilo vivendo"),
    (268, "Confiante em Deus", "alegre confiante consolação crê enfraquecido esperança fiel forte forças furacão guia haja hão leva mão novas ora perseguido perturbes porvir redentor sol tardança terás triunfante turve"),
    (269, "Louvarei ao Meu Amado", "alegria almas amado amoroso caminho carreira cingindo comprado confiança coroado dele digno enche entrar esperança exaltado fiel força fui glorioso harmonia louvarei majestoso melodia mudança nele nome prosseguindo quão seguindo seguro som suave verei"),
    (270, "Louvando ao Nosso Salvador", "alegre ando avante cantando celebrando conduz criador cumprida faltará feitos fim fulgurante gozo guiado guiará irei lavado levará louvando mansão nada obra porta prazer prometido repouso revestido senda sigo sinto suprirá tomando triunfante unido"),
    (271, "Na Mansão do Salvador", "aflição completa dará direi divinal dor encontrarei estando estiver eternal gozarei longe mansão moram morando mui nenhum nenhuma perfeito pesar quebrante reinarei salvos terei tribulação triste tristeza"),
    (272, "Quando Jesus Aparecer", "aparecer apresentar cear coroa crer crerdes dará desfrutar deter eternal existirá festa fronte gozará grei haverá iremos marchai podeis porá prazer quis recebereis resplendor reunirá santidade servirá sol sublime temer tendes teremos tiverdes trono"),
    (273, "Só a Ti Recorrerei", "acharei bom buscarei combater consolar dor encontrar encontrarei enganador grande hei lutas minh neste penas portes recorrerei refúgio socorro tentador terei trevas vencer virás"),
    (274, "Jesus é a Luz do Mundo", "achou betel brilhará brilhou cego cegos chamar densas dum fiel fores fui fulgor haverá horror irás luzeiros manda novo pecado perder perdido perfeita presos queiras rosto sol trevas vale viver"),
    (275, "Ó Acorda, Desperta!", "abismo acorda adora alento aniquilou busca crendo crê derramou desperta despertar dormente findar foge habitarás importas jazes libertar masmorra momento negra num obterás poderá procura próprio recebes respondes sabes sono sorte teres tormento tragar"),
    (276, "Em Canaã Eu Entrarei", "canaã cansarei caro céus dará ditoso emos encontraremos enfim entoarão entrarei esplendor festa habitarei haverá hino irei levará lutas muitas notórias nuvens passei país provas reino remidos repouso reunidos sião subiremos terei verdade voltará"),
    (277, "Salvo Estás? Limpo Estás?", "achado alvo branca dela eficaz enche farta fita fonte foste lado lava limpo mancha maná mui olhos pecado plena prazer pronto pureza purificador roupa sai salvo sangue seguir terás vencedor vertido vier vigor vives"),
    (278, "Levar a Cruz", "abrigo acharás adversário amigo auxílio bom calvário caminhar cansado cargas clamo derrotou escondido esqueças fiel fruirás lado levando levar mui neste peço sabendo sucumbiu vais vigor"),
    (279, "Ali Quero ir, e Tu?", "aonde celestial chegar coroar coros cristal desfrutar disserem dum entrar falou formoso irão jóias lugar mansão mansões mar morrerão morte nau navegue país portas preparar queres salvos sião termina tribulação vela"),
    (280, "Ó Jesus, Te Suplico", "amado caminho celestial consolar divinal fervor forte gozar gozo guardar guiar mão proteção queiras redentor repouso suplico vitória vizinho"),
    (281, "Vem Sem Tardar", "aceita amigo avisa conceder consolar convida depressa dons estende fartar firmar guardará larga mão perderão perdido perdoar perdão pobre queiras real receio recusar riquezas rocha salvar salvação soluçar tardar tenda tesouro trevas"),
    (282, "Que Sangue Precioso", "aceita alegres bodas comprou convite coroado derramou glorioso intercessor jubilemos lava lavou meigo pecador pras precioso recordemos redentor resistes saiu sangue sentado trono"),
    (283, "O Pastor e as Ovelhas", "abrigou achá ama campo colinas comovido cordeiros delicados desertos desgarrada desgarradas desviou direção dolente errantes gemendo las nove noventa obreiros ombros ouvem ovelha ovelhas pastor pastos penas perdida perdidas quietas rebanho redil vede zelosos"),
    (284, "Bendito Cristo, Eis-me Aqui", "aflição buscando busco convidas decidir demorar exposto favor grande livrar morte perdição perdoar perdão podes querendo servir tal valor vence"),
    (285, "Tu És o Meu Gozo", "bênçãos concedida céus encheu gozo inflamando inundando irei louvar manancial mandamentos momento operam pecados perto queimando recebida redentor salvação sustento trono"),
    (286, "Não Tarda Vir Jesus!", "anima cima descansar donde dor fomos fulgurante gozo guerra mar nesta olhamos queremos remidos revolta sangue santos tarda tenebroso tristeza virá viver voar volta ímpios"),
    (287, "Oh, Foi o Sangue", "aceitando algum amigo consolador deu dor débil grande guardar guiar iluminar lavou mancha maravilha mereço mostrou mui remissão resgatou salvação salvou sangue seja sofreu stou temerei tentador vencerei"),
    (288, "A Palavra da Cruz", "abriu caminho chamando cordeiro crer céus deu envergonho fiel firme ganhou infiel mensagem morrendo morte mui palavra pecador qualquer raiar redimiu remir salvou stá temporal veio vil vitória"),
    (289, "Sob o Sangue Teu", "achá asperge concede corrupção dons dúvidas enchendo expiador fazendo grande guarda lavar liberta livrar males manar pecador perfeita proteção queiras redentor refúgio ricos sangue satisfaz temor tentador tentação vencedor vigor vil"),
    (290, "Teu Espírito Vem Derramar", "arder clama clamamos confirma corações crente cumpra deixa derrama derramar dito dons enche escutes esperamos faça finito fogo guarda humilde milagres minh oração perceber petição possa purifica reter santifica servos templo tira tudo voz"),
    (291, "A Mensagem da Cruz", "alegro amo atrativos baixou buscar calvário contemplo cordeiro coroa dela deu emblema erigiu fim fugiu hei humilhante lar levar levarei mensagem morrer morreu nela nesta padeceu parte proclamar rude salvou santificação sofrer trocar vergonha"),
    (292, "Qual o Preço do Perdão", "curar deu divinal eficaz entrar fez libertar limpa perdão preço real resgate sangue santidade"),
    (293, "Jesus no Calvário", "aberta abriu calvário consumado cravada culpa cédula destruidor ego estranho excelsa exclamou expiou falaz ficou fiquei fugiu ganhou lenho liberto maldição minh morri nevou pascoal passou preço raiou rasgou rendeu riscou tirou uni unindo"),
    (294, "Eu Vou Com Jesus", "achei alegre anos aves brilha canto cima depressa dias elevo farol feliz mestre mui olhas pecado rei seguir sigo sobe sol sós triste vagava vago vala verás vivas vivo voz"),
    (295, "Novo Canto de Louvor", "acordes angelical canta canto consolação cordeiro deste divinal doce enganador firmou harmonia hino hinos inda inspirador irei jardim levar lugar noite novo ouve passar quão rocha rola salvou soar sombras traz vibrar voltar voz"),
    (296, "No Jardim", "beber cercar chegaram clamava completa constante crente cuidados cálice deseja dores falando falaremos flores forças jardim manto min muitos noite nova oração orvalho prender renovados seremos suplicava teremos teve tristezas unção vivermos viveu ímpios"),
    (297, "Abundância de Cristo", "abundantemente abundância alegrar alegria cansado caudal chagas contemplei continuação darei deu dissipou estou explicar forças fraco grande grato igual inda jubilar mui nome par pecados perdão provém pés rei salvação sedento sinto trouxe veraz"),
    (298, "Avante, Servos de Jesus", "ajuda avante avançai brilhe cerrai combater coroas davi fileiras fiéis foge gideão golias guerra inimigo josué lauréis levando levanta logo midianitas mui pavor pendão perder sai servos sigo soberbo trevas trezentos triunfante vencerei zomba"),
    (299, "Há um Canto Novo", "achei asas baixará canto caudal celestial chama contrito divinal doce enches encontrei fluem fundas ganhei guiou igual levará levou muitas nome novo numa nuvem obter prazer preso proteção provas riquezas trono vencerei voltará águas"),
    (300, "Nossa Esperança", "adoração aguardamos aniquilando arruína astuto autor breve buscar cercado coisas completamente corrupção dai daremos ecoa esperando esperança gran laços levantarão manhã momento mortos parar quebrando raiar reis ressurreição restaurar sempiterna sepulcro transformar usurpador vinda"),
    (301, "Vem Cear", "apanhar cear ceia comprou convida descer discípulos faminto fome irá manjar maná mistura multiplicou noiva partir passou peixe peixes poucos praia preparado preparou pães pão saciar sede sedento suportou tornar transformou vez vinho água"),
    (302, "Não Murmures; Canta", "abrirem bravio canta castiga ciladas cuida escravo esqueceu fraqueza hino iouvores israel leme levado libertado mara murmura murmuram murmurando murmurares murmures murmurou negou provando puderes quiseres razão revolto rugirem tal temas vez voarás águia"),
    (303, "Precisamos de Jesus", "brilhar calma caminhar decisão entrar errar escurecer fenecer final firme havendo lar lugar morte mui obter pecador perdão perseguição plena precisamos precisas preciso próprio qualquer resplandeceu salvação sol tribulação tribunal tudo veraz"),
    (304, "A Face Adorada de Jesus", "adorada amada apontar barco bravo brilhará cercar clamando contemplar dali desprezando dourada escura estarei estende face flechas governar gran grei hinos laços montanha ondas padeci perecer piloto quase satan sossegar traspassaram triunfar valer vela"),
    (305, "Campeões da luz", "ajudar alcançar alguém avançai batalha batalhamos campeões cansado cantai cantando capitão combater dura escudo exércitos falai flechas forças ganha hinos lauréis levai lutarmos olham peleja pelejar promessa ros soldados sós temer terminar vencendo vitória"),
    (306, "A Palavra de Deus é um Tesouro", "alumia arca ardis brilha certo chegará concedeu donde emanuel entrou escuridão esqueceu eternal fala farol guia igual leite lâmpada mansão maná mel mostra ouro palavra porto precioso resplandeceu rocha satanás senda tesouro toma viva"),
    (307, "Louvor ao Deus Trino", "adorai consolador divinal redentor tributai trino"),
    (308, "Só o Sangue de Jesus", "agradar alcançar corrupção dor expiador favor fiel for gran guarda lavado lavar libertar limpar livra mancha morada morte nesse ouro pagar preservar preço resgatou sangue teme tentação valor vil"),
    (309, "Ao Findar do Dia", "abençoar achamos amado aprendendo bênçãos congregados constrangidos continua crentes derramar deste dia doce emana encher ensinos finda findar gravar leitura lida livro nome palavra reunidos"),
    (310, "Avante Eu Vou", "abraão afim avante caro cearei corpo crer criador desfrutar destruidor elevará esmagará grei horror hão isaque jacó lado levará mansão olhando ondas profundo redentor regressará seguirei serei servos soará trará trombeta verei virá voltará"),
    (311, "Jesus, Meu Salvador", "achou alturas batalhou buscou carreira certo derramou descendo deserto dextra doçura escura estrela findar galardão lírio manhã manjedoura nascendo nuvens padecendo preciosa profundo receberei ressurgiu rocha rosa saron senda sepultura serei suave subindo verdadeira"),
    (312, "A Vinda de Cristo", "alarido alerta bendizendo corpo descer ecoar entoar entrarei esperando esposa fruir gozoso ingressar irei julgar justiça milênio muita nações nesse nuvens perene proteção prudência reinado reinar subir subiu terei trazer triunfante vigiar vinda voltarei"),
    (313, "Louvor a Trindade", "celestial consolador dai louvai trindade"),
    (314, "O pai bondoso", "andar andarei bondoso breve chama cheios cingirá contemplar coroa dará encontraremos espinhos esplendor face fronte gozo grande irei levará presto pro terei teve unidos verei"),
    (315, "Oh! Amor Bendito", "benquisto desfruta deste emanuel enches esplendor fiel fim forte gozo grande infinito luta morte possues pressinto sempiterna sinto vencedor verdade viu vivo"),
    (316, "Em Busca de Sião", "andei apanhei busca busquem campos canaã cantando desta egito encontrei enfim ergui escravidão fruto guiou hebron hei herança leite levou marchando mel melhor saindo sigo sinto sião tenda uvas vendo vinho vitórias vivas voltarei"),
    (317, "Jesus Vem Triunfante", "aberta aceitando amam brancas brilhando brilhante brilhará carregando chamejantes cintilante clamam derramado desperta encontro escritos felizes gran iluminando madeiro noiva nomes ocidente oriente ouvirão preparados raiando relâmpago rol sol subirá triunfante vencido vestes virá"),
    (318, "Ao Lar Paternal", "alegremente amoroso arrependido beijou bens camaradas contar contente deixou desleal disse distante dois esbanjou esperando fazenda fome herança história incauto jovem lar lembrou moço outrora paternal pudera queiras regressar relatou sustar varão via voltou"),
    (319, "Ainda Há Lugar", "aberta ajuntar bodas breve chama convidou convite crescem demorar descuida enche encontra entra espera festivas fim findar gozo inda lugar luta morar multidão ouve pecador perde porta preparou sala salva sombras terá vais vês"),
    (320, "Seguir a Cristo", "alento amas cidade confessa considera coragem cristão custa declara deu esconder espera galardão intento junto júbilo laço levar lutas montanha passo pede quebranta queres repouso resistas sedução segui seguir seres tamanha terás triste visto"),
    (321, "Só em Jesus", "abrigar acharás ancorar brilhante dardos deixa desfrutar desta ditoso dores encontrar escudo forte fruirás futuro garanto irás nau nele obténs oculto pecar poderás podes portanto porto receberás rocha sede seguro seja tocha trilhar tudo"),
    (322, "As Santas Escrituras", "alturas bondade brilhar condenação contam contaram continuar conto converta cravos criação derramado duma escrituras exaltou fruindo história humilhou juízo lança liberto lida numa ouvido ouvindo pregaram rebelde remidor santas tendo transforma traspassado velho vencido"),
    (323, "Levantai Vossos Olhos", "aproxima arrebatado bondoso breve brotos buscar cima dera dias dizendo donde endurecendo fará farão figueira flor igreja levantai levará mostra muitos noé olhos ouvir pecando pragas primavera produz redenção remidos tardando temer verão virá"),
    (324, "Jesus, o Melhor Amigo", "afundar ajudar amigo barco bonança calma chagas consolar deixar desamparar deu dor embravecem fiel força gozo inspira melhor minh nele ondas pecador ponho prestes própria salvar sarar torna traz valor ímpio"),
    (325, "A Luz do Céu Raiou", "alegre amou andei depois descanso enche entrou feliz fim findou gloriosa glorioso gozarei libertou louvar lutar minh morar noutro pecado prazer raiou revelado salvou sião tempo vivo véu"),
    (326, "Oh! Meu Jesus", "abalar abrigado ajudar amparado andar armado aumentar bastar braço desfarei dobrará encontrar encostado entregue espero estarei firmar forças hei invocarei joelho lutas língua meditar peleja procurar queiras repousar rocha temerei tendo testificará valor vencerei"),
    (327, "Teu Nome Precioso", "alegre almas braços continua despertar dirige doce doçura enche enlaçado estrela eternos fim fique fulgor gozo horror incomparável maligno neste nome passos pecado pio porvir precioso prosseguir protegendo rebrilha resplendente seguidor soar tentador terei"),
    (328, "O Pão da Vida", "ajudar algum alimentar amoroso auxiliar carregar confortar depressa descido duras falar fardo fazes galardão insondável jugo lembrar leve mandado passar perseguições produz provas puder pão redentor sanar saúde sentir tardar tardes verei vigor viverei"),
    (329, "Jesus é Minha Paz", "aceitei achei alegremente amar amou andei braços canto céus descanso deu faminto onipotente rei sedento tomou viva água"),
    (330, "A Fé dos Santos", "amaram andavam bens caro cavernas celebravam crentes cristãos dava despojados devemos encontraremos entregue espanto firmar inocentes julgados lançados peregrinos pisadas pranto prisões prosseguir recorriam refugiavam reunidos santos seca seguiram terrestres tribunais tristezas venceremos vis"),
    (331, "Ó Caro Salvador", "capitão caro contigo deste enfim falar faltará gozo grande intercessor irei levará lutarei manancial mão nenhum opera ora par repleto riqueza salvar senda sinto temor valor veio vela vero vigor virá"),
    (332, "Para o Céu eu vou", "abrigando aceitar amigos andando aproximando caminhando cansado chegue contra convidando desanimará escondido espinhoso findará for forte guiado guiará lado lutando mansão mestre nublado passos peregrinação repousarei seguro sigo surgem tentações trás velhos vezes voltem"),
    (333, "O Céu, Meu Lar", "carne dando fado feliz fervor gozarei lar livre louvando mui pés rei reino réu serei sofreu troféus verei véu"),
    (334, "O Fim Vem, Cuidado!", "abrigado aceita coisas cordeiro cristão cuidado depressa deseja eleita encontrará ficar fim fundamento garante isco morrer ouvir padecerá precioso procura queiras recusar remidor resistir rocha saiu sangue sincero tarda tentação tormentos ventos vertido viver"),
    (335, "Mui Perto Está o Dia", "amado andemos buscar descer devemos dia esperar fechar fiéis gozar gozarão havemos imensa iremos lado mui olhos par perto quanta rei residir tardará"),
    (336, "Oração de Elias", "além buscar carmelo chuva clamou consagrar consolador crente curvado descer elias forte frio horizonte insistência lgreja longe manda mandar monte muita mão negras nuvem nuvens olhar oração orou ouve receber servo surge trovão unção"),
    (337, "O Bom Jesus", "andar bom consolador deli dentro enfim estou feliz fonte livre longe manifesta nesta ouvir pecador real ressuscitou salvação sentir tesouro trevas viver vives voz"),
    (338, "Quero Jesus, Tua Luz", "abrigado abundante certeza cidade consolador consolação darei entrar estarei face fruirei guarda habitação junto lei louvar meigo minh nele neste nome pecado quiseste receber resgatar revestir sangue satisfaz sião tentação terei trono vendo vil"),
    (339, "Jesus Ressuscitado", "agradecer alegria amado comigo concede concedeste consolador consolação deste dolorosa força grande guia imenso morte plena radiosa real ressuscitado salvação santidade traz viver vontade"),
    (340, "Um Povo Forte", "buscavam cai cenác clamar descido descuidado destemido discípulos ditoso dom fará fogo forte maravilhoso oração perseguido pertencer poderás podes proclamando reunidos revestido sai sejas sorte sublime surge tais teme terá unidos vais vento visões"),
    (341, "A Aspiração da Alma", "achará aspira aspiração casa crentes descanso encontrará ensinará fervor habitar justiça lar minh mui ouvir pecador redentor servi soar voz átrios"),
    (342, "As Cordas do Coração", "acordes afina afinadas afinador afinados afinar afinação afinou agradável almas além calvário chega cordas cuida estiveres fomos gólgota harmonia instrumento louvar mestre minh nova outorga provar queres refina som terás tocar tom transformados vibram"),
    (343, "Abre o Coração", "abre aceita almejas amanhã bater bom crer depressa escutas meiga obter ouvindo pecador salvará salvo sinto tardar voz"),
    (344, "Um Amigo Entre os Lírios", "adorado amado amigo anjos brilho busco caro chamaste deixa desfrutar face graças isento libertar lírios males meio morreste ouve preciosa produz provaste radiosa rebanho revelar rio rosto scondas segui sol sorri stá vales voz"),
    (345, "Oh! Tenho Gozo", "asas certeza conhecer consolador crente crer desfruta deu dum esconde fervor fiel gozo imenso irás israel juntos louvemos promessa real rei reino repleto salvação salvou selou vigor vive"),
    (346, "É Meu o Céu", "aleluias andei avistei bandeira bater cantarão cesse cima combater condenação descansado descansarei espera estarei fora irei louvarei multidão nenhum olhei palmas perecer rasgou sagrado sangrenta sodoma soldado solitário subirei temerei trono vencer vertido véu"),
    (347, "Vem a Cristo", "abrir alcança anela chama confiança crendo crê demora divinal firma gozo livrar logo morte obterás pensa perdão portas prazer redimir temendo"),
    (348, "Longe de Jesus", "cai chama confessa dará encheu escuridão escuta expiador fenecer grilhões lavar longe morrendo morreu murmurar negra pecador pecados perdão plena preciosa quebrou real recebi salvou sofrendo sofreu solidão vagava vencido verteu vil vim viverás"),
    (349, "Os Dons do Céu", "abençoa abundantes aguardamos altos bom buscar chuvas consolador constantes crentes céus dons esperamos face glorioso manda mandar prometidos queiras reunidos suplicamos tementes vigor"),
    (350, "A História da Cruz", "aceita consumado desfazendo dor dura exclamou fim grande história inda lembra lenho lido malfeitor manando morrendo morreu padeceu pecador perdão queixou raiou rogou salvou sangue sofrendo suplicou trevas"),
    (351, "A Felicidade da Salvação", "apanharei apenas cadeia dextra divinais entoam estêvão exultação felicidade gotas gozos gólgota importarem louva mananciais manarão ouvido passado paulo pedradas perguntares pombinho responder salvação secam seguros sequidão silas sucumbiu séculos teve tom tronco visão"),
    (352, "Jesus, Nossa Esperança", "almas apresentamos chamado confiança contritos corações esperança fervor lava los purifica ramos resgatado rogamos sangue santifica suplicamos verá vide"),
    (353, "Vem, ó Pródigo", "abriu aceita aceitares alto completo crê deixa demora descansas dura entrega erguido escuridão favor gozo horror inda jazia mensagem parti pecado perdão porta prisão pródigo remiu salvação terás trevas trouxe vagas"),
    (354, "O Cuidado da Alma", "ajuda ajudar celestial confiar consagrar cuidado descansar entrar firmar guardar imortal minh obter prepara proteção reino serviço velar"),
    (355, "Fala do Amor de Cristo", "abriu aflitos alegria alvor além bênçãos caminho canta confiança dia escuridão esperança fala flui ganhou harmonia inaugurado lavou levanta noite obtém pendão perdidos rasgado redentor redenção sangue templo triste vertido visto voz véu ânimo"),
    (356, "Oração Dominical", "afastar almas anúncio benfeitor conforme dia dominical faltar faltas feito fizeram glorioso livrar mar nome oração perdoado perdoar pertence pão queiras reino saciar santificado sedentas seja tentação universo"),
    (357, "O Fim das Lutas", "alegres amigos bênçãos cessar criador descanso dia fim gozando gozar gozo grande hei hão lar louvando lutas morrer país penso prazer rio rosto sorrir ventura"),
    (358, "Senhor, Manda Teu Poder", "batiza casa cenáculo concedeu concedido consolador crentes descido encheu exaltando falaram fervor fiéis fogo línguas manda noutras num oravam pedirem prometido real rei servos transbordaram unidos veemente vento vieram"),
    (359, "Vem a Mim, Pecador", "abri amo clamo convite crimes desprezes ditoso feliz ferido fraco fui glorioso gozo libertar livrar morri orgulho padecendo pecador pecados perdido perdão poderoso quis resiste sangue sofredor trilho"),
    (360, "A Preciosa Fonte", "abriu clara consolação corre cujas cura deu divinal encontrei entrar fez fonte impura minh nesta perdão preciosa pura purificar purificação real sabor salvação sanadora sara sedutoras tornou veste águas"),
    (361, "O Peregrino da Glória", "aberta cantos chamar chegarão cheio cântico dourada entoar entrada entrarás escondem escura estarei gloriosos harmonia hinos louvores morada ouves peregrino porta queres raios salvos saudades segue soar som suave terminada unirás vitória volta últimos"),
    (362, "O Espírito Diz: Vem!", "beber beberás bebeu criatura deu diga escuta fale fartarás fonte infeliz maravilhosa noiva obtida pecador perdida puras quiseres recebeu saciar sedento sequiosa tardar toma voz água águas"),
    (363, "Consagração", "ande carmezim concede consagração contigo feliz foste morreste porei salvaste sangue santificação sofrer verteste viverei"),
    (364, "Oh, que Paz!", "alegra amados andar caminhemos consolação dor emanuel enche fiel for goza israel nele pecador pensando perdão possui prova recebo sinto vencer vitória viver"),
    (365, "Confiança em Jesus", "acudo ansioso ardis braços cego cessar confiança confiar consolar deixes descansar desejando dissipar débil fraquinho fruir habitação males minh nada nele obter perdão pobre pés reinado reter tempo tentação toma valer"),
    (366, "O Nascimento de Jesus", "adoração anjos belém bendita cantam céus demos desceu dom dores enviado fez filhos gozo gratidão grato homens humilde levar louvar louvaremos nasceu nascimento ofertar padeceu par pastores produz quis salve sendo sentiu traz trouxe"),
    (367, "Espírito Consolador", "acende celebraremos celestial concede consolador deixou demonstrou eficaz fervor fogo fonte humilhação imortal infunde morrendo perdão preciosa pão redentor símbolos unção valor"),
    (368, "Jesus, Tudo prá Mim", "ajuda ando bíblia certo chegando comprou conduz confio conheço contra culpa deu diferença ensina ganhou habitar imenso injustiça irei livrou lutar morada morto mostrou negar padeceu perdido perto piloto preparou santifica triste tudo vivo"),
    (369, "Sob as Asas de Deus", "abrigado achar acho aflito alegria asas confiando descansado descansar descansarei encontrar estou fui gloriosas gozo guardar inda livra nele noite perfeito poderosas preciosa preciosas promessa protegido redimido refúgio temerei"),
    (370, "Grato a Ti", "cheio consagrado consolação deste encheu fim fizeste gozo gratidão grato humilhado liberdade ninguém poderia pregado pés sangue santidade tudo vencer ventura verteste"),
    (371, "Breve Vem o Dia", "agonias almejo breve caminho canto cessará cessarão chegar confia deste dia dor escutando findarão gozo grande guia haverá hei lutas males ouvir pranto remidos segui trilhar voz"),
    (372, "Vencerá", "achará audaz batalha combate combater cumprirá dará desmaiará espargirá espera evangelho falhará firmado firme forças impera inimigos jeová libertar lugar mui nele novas possui promessas qualquer sangue trevas triunfar unido vacilar vencer vencerá"),
    (373, "Vem a Teu Salvador", "achar aflito calma confiante consolação curar doente errante escravidão fruirás humildemente morto pecado pecador perdão salvar salvação salvou segues sentes terás vieres vil"),
    (374, "Vida Abundante", "abundante amado amarmos certeza consolador consolação cuja dado derramou deu encha exultante fortaleza gozo perdão pureza queremos santidade veraz verdade"),
    (375, "A Igreja Universal", "abalar acabar bom colocou consagrou contigo corpo deu enche encher estou expirares fervor firme fundada igreja imensa lugar membro pedra plena reinará remido rocha salvação sangue templo triunfal universal vencerá veraz viva"),
    (376, "Vamos Todos Trabalhar", "aceitaram campo cenác compungidos creram deixarei devemos discípulos encheu enviarei falará habitar ide judeus lembrar línguas mandado novas ordenou palavras pregar prontos receberá ressuscitar reunidos rogarei salvará selo sinais sinal star subiremos trabalhar órfãos"),
    (377, "As Promessas Que Não Falham", "abandonar abraão alivia amargura amigos ardendo belas brilhantes combaterá confia contando crendo creu cumprirão escura estrelas falham firma fores inimigos livrará montes perseguido peças promessas ros sentas sofrimento stão tornam tremendo ungido vastidão vendo"),
    (378, "As Pisadas do Mestre", "acima adestre ando ave avisto bendita busca carinho descansar desejo devo dirijo doce enganar exaltar galgar guia levar maligno mansidão mestre misericórdia ninho orando passos perto pisadas porfia quão seguir sigo sião sustenta terno"),
    (379, "Salvo de Graça", "alegria andei brilhar choro cravando crer demos descanso enfim entrar errante esforços fazendo ganhou gozo grande lei levou liberdade longe louvar melhor par pecados perdido prantos preceitos promete reino salvo salvou sedento valer vitória"),
    (380, "Abraão e Seu Sacrifício", "abraão anjo encheram erguendo estendas fidelidade fiques fizeres imolá interrogação isaque jurou lenha lentidão mandato matança mato matá moriá murmuração obediência oferecemos outono ouvida patriarca porquanto proverá resposta roseiras sacrifício sirvamos tamareiras tomando trouxemos"),
    (381, "O Cordeiro de Deus", "altar alva ame castigo conceder cordeiro cruel culpa derramar determinar expiou fortes fundo grandíssima herdar holocausto horrenda imolado inferno liames oferecendo padece pendurado proclame quanta remorsos rompe sentiu sofre sofreu subiu sucumbiu tece tomou"),
    (382, "Olhando Para o Calvário", "abrigo achei avistei calvário clarão cordeiro crucificado derramado desta dor expiando fonte grande imaculado livra morreste olhando pecado pecador pobre revelou salvação sangue sofrer trouxe vil"),
    (383, "O Sustento da Alma", "abatida achamos amar bastante bodas chegados cheia criaturas desfruta devemos entraremos esposa exultante felizes fervorosos festa formos formosa haja livramento mostrou ociosos preparada proclamemos resaurgiu sala sepultura servirá sinceros sustento tiver trabalhando vencido vestido"),
    (384, "Sinto Vida do Senhor", "cobre consolador desejo eternal favor firma guardar habitarei lei liberdade perfeição permanecerei produz repouso rocha salvar sinto sustenta tempestades veio vigor viverei vivo"),
    (385, "Amemos o Senhor", "amemos amou bom celestial consolador consumador crer culpa daquela derramou desce divinal enganador ensinador eternal expiou fonte lavou nele pecado sangue"),
    (386, "Vencidos os Combates", "abaterá arma ataca aumentará bodas combate combates contra desfará dimana edificará erguer esperando esplendor esposa fabricada furor guarda hás inimigo justiça patriarcas posição profetas rancor recordação sofreste sublime temas tenda unção vencerá vencidos viva"),
    (387, "Derrama Teu Espírito", "antigos brilhar centurião conversões corações deixa derrama desperta dormem escuridão fazendo ficamos fizeste fogo grei guia indispensável jardim jerusálem manda muitas obter operaste orar palavra prometida proteção sentir sofrem sono tempos unidos unção vivifica"),
    (388, "Canta, ó Crente", "alegra anda canta cantas canção cheio clemente confiando crente deixa doce dor feliz frente guarda levanta louva medroso mão noites pesar potente profundo resistes socorro sol tiveres tristes turbação veraz"),
    (389, "Lava-me ó Deus", "alegremente alva batizar bom crer criação cumprir descansarei força honrar imersão invocarei justiça lava minh nome nova obra pecados puro ressuscitar sangue seguir sepultar servir sublime torna valor águas"),
    (390, "Um Coração Bondoso", "acima alcança altar amarguras aprovação arão beneficio bondoso castigado consagra cova custa densas enterrar exortação gemido imensas isaque jacó jeremias lamenta manando oferecido ofertar pessos precisas quebrarão raquel rebelião sacrifício sarar sonhador tornam via"),
    (391, "Jesus no Monte da Ascensão", "altar ascensão assustado cenác compreendeu cumprir darei descendo detei dias discípulos disse ensinar esperar falaram fogo gloriosa irás jerusálem línguas mandara monte noutras orar pedro proclama proclamar prometeu revestidos revestir subir testemunhas vento voltou"),
    (392, "Peregrinos Somos", "abraão alcançar bela chegue consolação desejo deste dirigido doce feliz findar gozo grande irei jerusálem labor lar lua morar mui país peregrinar peregrinos prazer promissão pátria queremos querida querido sião vencer viajar"),
    (393, "Há um Amigo Mui Chegado", "aberto agonizava ajuda ama amigo bom certo chama chegado conhecê dai derrama deserto guia labor maná mostrava muda mui nele pecado pecador pedra permitida resgatava salvou temor"),
    (394, "A Mão ao Arado!", "aflições aguardando alegremente andando arado consola consolará constante coroará declina desanimes desfrutares escurecer esquecerás largares levando lidares lindo maior mão novas pensando perdoando perseguições pesada pesares precisa proclamando pôs soldado sufocando trabalhando tribulações vigiando"),
    (395, "Ide por Todo Mundo", "aberta anunciai confiando convosco crer dado dizei ensinai entrada entrar estou grilhões guardar ide irei lar liberdade livre mandar mar morte nações oferece porta publicai ressuscitei salvação séculos traz venceu"),
    (396, "Além do Nosso Entendimento", "abrange alto além atendeu atinge calculei dando dum enche entendimento estado fez glorioso grande imenso inaudito infinito intento malfeitores par pecadores pensamento perdoou perigoso pobres rogos sacrifício salvou sarou sofredores sondado sublime triste valor"),
    (397, "O Salvador me Achou", "achou algoz calvário consumado desprezes detenhas dextra favor fie ganha goza hão indigno intercede mediador minh morrer mortos ouve ouvir pecador pecados perdão redentor resgatou ressurgiu sepulcro subiu temor terna terno venceu vitória voz"),
    (398, "Perto do Meu Redentor", "abrigo amparo bondoso descansar desejo encontrarei envolto estando frui fulgor guardará lugar mui nada ninguém perto poderá proteção redentor segura seguro temerei temor tentador terei tirar tristezas verei"),
    (399, "Terra de Jesus", "além brilha deste dor entrar fulgor lugar luto mansão morte país portas preparou queres salvou terão trevas"),
    (400, "Em Jesus", "adorável alegria barco bendita desfruto dia doce estou firmado forte harmonia hei inabalável inaudita incomparável infinita minh morte norte rocha ruma salvação temerei temo vencer vivendo"),
    (401, "Jesus Voltará", "acorda alerta bodas bom breve certa chama clama consola crente cristão deste dores haverá mar mostra pecadores proclama recebe rei revolta tristezas tudo vinda virá volta voltará"),
    (402, "Ao Gólgota", "agonia alto anda ascende cobrindo contempla contente entoemos exalto excelente gólgota hosanas inocente jubila lava medita mercê minh onipotente onisciente orando ouvirás penar recebe rendemos rubra sabes serpente sobe tentar torrente velha vertido vês"),
    (403, "Gozo Real", "crer crês derramou desceu deu dum dura gozo mercê morrendo mostrou passo pecador perdão qualquer real recebe redentor salvar salvação sangue sinto transforma"),
    (404, "Em Glória Virá", "aguarda alerta alva amoroso breve buscar crente cumprir descerá emanuel envia espera esperai estai estrela evangelho fiel fim grande imolou logo manda nuvem nuvens orando subir veremos virdes virá vistes voltar"),
    (405, "Queres Perdão", "ama capitão chora cima corrupção creio crer crê desanimes enganador farás força furor guarda hás inda inimigo liberta lutas meio morto olha perdão provas queres repouso ruge salvo segue tentação teres terror terríveis torno"),
    (406, "A Sombra do Meu Redentor", "abrigar abundante alçar bandeira bom braços chegar consolar contrito céus defender deter encostar lançar levar preciso presto pátria pés redentor sombra sublime virá"),
    (407, "Ó Criador Bendito", "aceita alegra benfeitor buscamos cantamos chama confiança contente contritos criador derrama deste ensino entrega esperamos esperança excelso fonte gratos herança hino louvamos manda onipotente perdido profunda pão remido sempiterna sente suplicamos supremo unidos viva"),
    (408, "Abre os Meus Olhos", "abre abro acudo aumenta belas consagro consolador cristal cumprir enche entrar esplendor frágil gran humildemente lindo louvar luta mente olhos ouvi ouvidos ouvir palavra palavras palácio porta põe refúgio rosto sustenta terna ungir vencedor"),
    (409, "Trabalhadores do Evangelho", "alturas andar baixando cansar ceifareis confiando confiar correrão devemos esperam estamos evangelho falhar fatigar força forças fracos hão novas obterão quantas revezes sejais socorrer socorro subirão suprirá tereis trabalhadores trabalho velhos vezes voarão águias"),
    (410, "Jesus Meu Rei Glorioso", "aceita ajuda amado amar amigo bastante consolo constante deixando desta ditoso enchendo entregar escória feliz glorioso grato humilde lado livrar lutas mui paciente pastor prostra pudera rei rendida servir sigo torna trono tudo veio"),
    (411, "Nós Somos Teus", "aceita andar bom caminho cheios compraste faze graças leva louvar morrer nele pastor percorrer quis recear rendemo salvar união veraz voz"),
    (412, "Jesus Cristo, Bem Amado", "adorei alegrar amado bom canto compassivo desça devem dom elevem galardão grande guia guias honra nome ontem poderoso redentor salvação seja trino vitória"),
    (413, "Meu Pastor", "andar bordão cabeça cajado caminhando caminhar campo casa companheiro confiar coragem cálice dulçor eternamente falta flor habitarei inimigo mesa misericórdia nela pastor possa prepara proteção próximo refrigera saciando temer temerei transbordante unge verde óleo"),
    (414, "Tem Compaixão do Pecador", "achará compaixão doa encontrará lavar pecador perdição perdão purificar rei reis salvação sangue"),
    (415, "Jesus Te Quer Curar", "andam anos cegos comovida confiares coxos crentes crê curado curar curarão demônios expulsarão fala gentes glorioso ligado livrar males mortos médico nele ouvem poderoso salva saram satanás seguirão sinais surdos terna verdadeiros voz"),
    (416, "Quando o Povo Salvo Entrar", "alegria anjos brancas cordeiro coroados crentes dominará encontrar entrar grande haverá hão lugar milhares morto multo remidos salvo terá trajar tribulação vencedores verão vestes vivo"),
    (417, "Bastante Para Mim", "achar achei alegre apenas basta bastante brota cantarei cessar corre cravados crer direi dor duma enfim fonte fui grande insondável mar meio pecados pude vacilar viva"),
    (418, "Sou Um Soldado", "alcançarei batalha celestial cidade confiando coroará depois dor fiel for forte galardão grande hei levar lugar lutaram mansão mui pelejarei rei servo sião sofrendo soldado temerei temor terei trás verei voltar"),
    (419, "Vinde, Pecadores", "beleza buscar caminho cantaremos certo crentes deserto deu dominando encontrar fortaleza força fracos fraquezas gozo guia história inferno logo montanhas mui pecador pecadores perdido perto planos redentor salva sangue superno temores tiram verteu vier"),
    (420, "O Que Buscas Ansioso?", "alegra altos ansioso belas buscas cessar chegar crente desditosa dores entrar espinhos eternal excelente fim flor flores fruirás grado hão larga linda murchará num odor perdição precioso produzir repouso rosa saron seduzir terás trazem"),
    (421, "Careço de Jesus", "alegrar careço"),
    (422, "No Céu não Entra Pecado", "aflito astros banido bastante cheios enterros entra erguidos espalhados fadiga ficar hei idades linda luto mudados muitas necessário ofuscar pagar pecado pobreza podarei quebrantado riqueza rodeado romper saudades sepulcros terrestre transformados velhos vestuário viverei"),
    (423, "De Ti Preciso Mais", "atender compaixão comunhão conceder consolador contigo dador dom eficaz enche encher esplendor face guardar humildade imitar instrução lua ouvir preciso pronto queres reino servir silêncio submissão tabor transfiguração transformação valer veraz vigor voz"),
    (424, "Seu Precioso Sangue", "comprou cravou curou pecado precioso salvou sangue"),
    (425, "Perdido Andei", "abracei abrigo andei avistei calvário confesso confiei cri entrou esperar fiquei fitei forças guiado iluminar imerso levou nessa perdido prazer promessas pude salvadora salvei satisfação sendo senti sinto stava trazer unido veio viver vãs"),
    (426, "União Dos Irmãos", "achamos ansioso ardor batizar bom busca buscamos certamente chegarmos concede confirme consolador eia encontrarmos escutar esperando festa firmes fruímos haverá humilhamos ouvir palavras passar presença prontos reunimos sentenças testificar união unção vedes visão vizinho"),
    (427, "Vai Orando", "ajuda cansado cercado consolar consolação curará dará doenças dor eleva faltas fervor firmeza furacão incertezas labor mitiga mui ora orando passará pedido pesar presto provado releva responder sofrer soprar tarda velando voz"),
    (428, "A estrela da Alva", "alva bendita bom bondoso direção emanuel enche estrela fiel fulgor hebreus iluminou mandou manhã mostra perdida raios salva salvou vaga vigor"),
    (429, "Escuta o Evangelho", "abraça aceitar aceitas altos atenção conselho contrito céus dando desejoso ditoso divinal dor encher escuta evangelho gozo grande pecador perdido perdão perfeita salvar salvação sangue terás verdadeiro vertido voz"),
    (430, "Evangelho da Salvação", "alcançarão algum arca avistar baterás cansada chamada corrupção corvo criação dali despertado evangelho fatigada fazes marcas mortos numa ouves ouvindo pomba porfia porta pousar quererás refúgio repousar salvação transforma velho verá via vindo águas"),
    (431, "Cristo Chama o Pecador", "aceitarás amanhã atroz bela benfeitor chama chamar esperar feliz lavar manchado ocasião ouves par pecador perderás queres salvação tardar tardes tempo terás viverás voz"),
    (432, "Consagrado ao Senhor", "canção carmezim consagrada consagrado consagrar enche eternal falem faze faça fervor habita jeová labor lava lábios minh numa operar ouvir possam possas prostrar puro pés recebe sangue santos seja tempo toma voz"),
    (433, "Sois Benvindos", "abraçai amistosa benvindos bons campeões congregação demos denodados difundir dilação elevamos fervor fileiras fingidos fiéis jeová jubilosas louvores lutadores lutam obreiros parabéns recebei rei reine soldados superno trabalhar trouxe verdade vigor vinda vindos vozes"),
    (434, "A Teus Pés", "abatida abrigo acho aflição bondoso buscarei compaixão concede conflitos consolo constante cuidados desfruto doçura encontro escutando esquecerei face horror igual livra maria mente neste olhos palavras passado pesares possa proteção pés salvo seio terna"),
    (435, "Jesus Me Levantou", "abismo amante baixou chamou compreendo deu dom dor dum estando expirou feliz ganhou horror levantou minh plena pregado quanta recebi resisti salvação salvou sofreu sombra vil voz"),
    (436, "Crentes Cantai!", "adoração amou ardentemente ardor autor bondade cantai crentes criador dai demos dextra eficaz entoai entoei entoemos exaltado fervente honra imensa infinita instruidor lindo louvares louvei louvores mandou onipotente onisciente preceptor sinceramente tributemos trindade vasto"),
    (437, "O Dom Celeste", "aonde batizar batizou bom caminho continua cálice dele dom estranha evangelho falar falarei homens louvado língua mandar mandou obedecer par quiser recebei receber rei seja selo testemunha transbordar trilhar visto viu"),
    (438, "Voltai-vos Para Mim", "brilha celestial conduz deixai dele disse dom encontrareis enfim esperai estrela falou fruir fulgor horror jazes justiça manhã mortal olhando pare passos real remidos sairão sede seguir torrentes trevas ventre vigor vivas voltai água"),
    (439, "Aos Pés de Cristo Prostrados", "abundante achar adoramos ajudar ama bastante cansado consolo crentes exclama favor faça fomos guardados lavados madeiro maldição morrendo mortal pregado prostrados prostramos provado pés quanta quanto redimidos ressurgido sede sofremos sofrendo vemos vertido verá"),
    (440, "Faze Já o seu Querer", "amigos carregar conhecer consagrar cuidados dará deixarás deves dons encontrar faze fazendo firme gozo guie inundará limpará manchas permanecerás preparar queres seguirás tardar verdadeira viver"),
    (441, "A Chuva do Consolador", "abrirás bom celestial chama chuva consolador dele derramarás descer destrói fervor fogo furacão inflama manda mediante oração pedimos possa queima templo unânimes unção vivifica vivo óleo"),
    (442, "Breve Verei o Bom Jesus", "além aparecer bom breve desfrutarei dia disso donde dor falado galardão gloriosa gozarei hei hão irei jeová levará lindo livre mansão naquele plena prazer receber repouso santos serei verei vinda virá viverei"),
    (443, "Larga o Mundo!", "aceita banquete casa cear chama cheio consolador convida convite desfrutar despreza divinal entrada espera faminta fartar feito franqueia larga manjar mansão paternal pregado preparou profano pronto queremos queres recusar satisfaz sofreu tiver tudo voltar"),
    (444, "Escuta, Pobre Pecador", "aceita achamos caminho certo deixando derramou dor entregar escuta esperança fruirás grande nele pecador perdão pobre real receber redentor redimir resgatou salvar salvação sangue satisfaz sofrendo tardança"),
    (445, "Resgatado Com O Sangue de Cristo", "alcançar calvário chegar comprar diante dívida encheu entrada favor fui justiça lançar livrou manado obter ouro pagou perdão pio poderemos prata preço pude raiou receber redimido remido resgatado sangue satisfazer terrestre tesouro valor vertido"),
    (446, "Ó Vem Já!", "aceitar bom cansada cansados chama confia darei demores derramado dor enfim gozo livrar longe mui oprimidos pecado pecador preso redentor reino salvação sangue sentes vagas veraz vindes"),
    (447, "Nascer de Novo", "acharás alvo andas batizado brado canta clara demores desceste escondido escrita estarás estreito feito foste habita jordão lida marchas mágoas nascer nascestes novo passaste pertences portal preparado recebeste segues tesouro vestido vindouro vives águas"),
    (448, "Crentes, Avançai", "agradar alcançar andai avante avançai conduz contra crentes crê dando dará deu divinal firmes fruirá gozará guia lar luta lutarmos marchai nele pelejai redentor salvação sangue triunfar valor vencerá verteu vicio vitória"),
    (449, "À Beira da Estrada", "achar almas aproximar beira buscam conhecerás dirá enfermos escriba esperam espirituais estrada existem falar falará famintos farás jornada muitos multidão passarás perdidos perecer pronto pão quantos receberam saciará samaritano senda socorrer tais terminar vais"),
    (450, "Sol da Justiça", "brilha caídos celestes completa céus deserto deste dourado dum espalhar esplendor fala formosos fortes fulgor inundar jardim justiça levar lugar perdidos proclamar qualquer raios resplandece resplendor salvação sol trabalhar traz verdadeiro"),
    (451, "Meu Jesus Vem", "aberto achará anjos breve chegada começará corpo dando desaparecem descanso dores encontra estrelas festa gozará harpas haverá indicam lado louvores mensagem mil profundo prometido resplandecem sinais tangem tardará testemunhos testificam transformado tristezas virá voltará"),
    (452, "Seguirei a Cristo", "for seguirei"),
    (453, "Deus é o mesmo", "abundante alegre alguns avivamentos batiza bom crentes cura encheu enviando espiritual eternal falar farol ferventes fervor lembrar livrou mandar mudado mudará orações ouvimos ouviu pentecostal permanecerá primitivos recebem salvação tempos tudo"),
    (454, "Alegrai-vos, ó Remidos", "alegrai cantai cordeiro dai digno domínio fiéis glorioso honra horror pecado redentor rei reis remidos resgate vaticínio vencereis verdadeiro"),
    (455, "O Povo de Deus na Terra", "alimenta além beber braço contra convida crendo darei enche encherei envia espera guarde guerra guia logo mansão pedem presto profunda profundo purifica quão reinar sacia salva sede sedenta seguindo sentindo sinal vigiei vive água"),
    (456, "A Fonte Transbordante", "abrigo abriu abundantemente abundou alvorecer buscar cansada consagrou derramado derramou dia exaltarei fonte imenso irei mar pecado perdido perseguida pomba porta pro profunda reconciliou rejeita réu salvou sangue superabundou transbordante veio"),
    (457, "O Festim de Glória", "anjos aparecer apressa bom celestial corpo dia ditosa esperando esperar estou evento face feliz festim firme fonte glorioso hei hás lar mortal mui nesse nuvens prazer stou tiver vinda voltar"),
    (458, "Guia Meus Passos", "aprisco atrai belial bom chorar conduz consolação envolto errante escravo estrada faminto fiéis flor fonte fora glorioso guia infeliz lar larga leva ouve ovelha ovelhas passos pastor pecador queixa redil simples triste vales vergéis"),
    (459, "As Firmes Promessas", "abrigar apertos arde arrebatar auxílio bastante brilharão brilho certo cessa corajoso coroa crente dará descansa estrelas extingue falhando falharão falta febre firmes guarida levar montanhas mui promessa promessas socorro tentado terrestre terás traz virá"),
    (460, "Dize-o a Cristo", "abatido amigo aumenta cansado cercado chegares confia confundido contenda dize débil emanuel entrada feliz fiel fim hostes jornada olha pecado rugem saíram segue senda sentes tentação torno"),
    (461, "Jesus Chorou Sobre Jerusalém", "ajunta aparente apedrejas cedrom cega chorar chorou cidades contemplada descuidado escondeu esteve exterior fechaste galinha jerusálem juntar lamenta lamentar levantadas multidões oferecida penetrante pintos rebrilham rejeitam rejeitaram repete segues sobe tarde tornaste torres vacilantes"),
    (462, "Glória ao Salvador", "grande redentor"),
    (463, "O Povo de Abraão", "abraão alegre brilham caminhando certo chegarei cheio cidade conhecerei contente dirigido estou glorificar gozarei inimigos jeová marchando orando povos presença ruas servirem sião sustentado trabalhar tristezas vejam viajou vigiando áureas"),
    (464, "Plena Graça", "guardar lavar plena puro salvar sangue"),
    (465, "Ele Sofreu Por mim", "afronta anjo arimatéia caíram conduzido corte culpado deram empolgou espinhos esponja expirando furou guardas havia inocente josé julgado milagre padecendo plano puseram removeu resplendem roado sentia sepulcro sofreu tomou tragou vibrou vigiavam vinagre vis"),
    (466, "Que Maravilha", "aceitares adorado adoro almeja amigo amo breve clamo confiares conheces crido céus descer deseja deusl deve enalteces irás jubilando louvando maravilha nele recebido rejeitado seguir"),
    (467, "Sobre as Ondas do Mar", "abriu assustar bonança cabo deserto duvidar ego falhará fartou forçado lutar mar maravilhas montanha muda mão nau navega ondas pedes poderás recordar remos revelar sendo serás socorrer solta suster tempestades tirar toma tribulação verás"),
    (468, "Cristo Está Chamando", "andar bebe carregando chamando compaixão cristão esperando júbilo laço livrar morte paciência passo pecado pede perdão queres recebe resistido rompe salvar salvação sangue seguir terá terás tornares vencido visto viva voz água"),
    (469, "Ao Estrugir a Trombeta", "altos angelical anunciar chamar creio cumprir céus der enrolado espero estrugir for fruir gozo mar música neste nome ouvir ouvirei passarão permanecerá proclamar promessa pronunciar sol suave trombeta"),
    (470, "Batismo", "almas amado batismo batizados batizar branco canto conceder conquistar contigo dado fim jerusálem louvarão mortos nome novo pecados puro receberem reinarão ressurgidos selar sepultar vestidos viverem águas"),
    (471, "Avançai Fiéis", "abatidos arvorado avançai avançar brados capitão clamor coroar destemidos escravizados escutemos feridos fiéis forem fortes frente gideão guerra hostes ide ilusão infernais lutar pavilhão povos própria sejais socorro soldados terror triunfar turba vanguarda vencer"),
    (472, "Em Meu Lugar", "bondoso cravou lavou lugar minh padeceu pecado precioso salvar sangue sofre tudo"),
    (473, "Outro Bem Não Acharei", "acabará acharei amar andar ansioso bastante buscarei confiar durar enganador fiei fim findará hei homens melhor nele neste procurarei rei saciar stá tempo terá tudo vaidade vive vivo"),
    (474, "Paz, Doce Paz", "andar brota consolação dará descanso doce dor fará fruir morte pecador porvir sangue separação tardará temo tereis terror trazer trouxe venceu"),
    (475, "Em Belém", "adoração alta anjos belém certeza céus demos excelso herdar honra horror infinito jubilar louvemos magos mandava nasceu nascido perdido profundo príncipe redentor refulgentes rei salvar traz veraz voz"),
    (476, "O Cego de Jericó", "atende bartimeu bom cansar cego chamar clamar clamava clamor compaixão devi dizia escutar faça forte gritava inda jacó jericó logo louvou mandou multidão passava pergunta queres quieto repetia respondeu salvou tardar veio vendo viu"),
    (477, "Sede Fortes", "adormecidos alegria amai andai anjo braços buscai chorando conduz encontrarão esplendor fervor ficarão fiéis fortes fruireis garantindo libertos lida muitos naquele orando ouvirão remidos santos sede tendes transformados trilharem velai vereis vinda visto voz"),
    (478, "Eis-me Jesus", "alegrarei bondoso buscar concedeste confiar contrito darei derramando deste desça discípulos dons dura encheste estranhas falar fizeste flux glórias louvando línguas maravilhoso mil naquele negará nove padeceste pede promessa realizando selar trazendo veraz verdadeiro"),
    (479, "Ao Raiar do Novo Ano", "ano ardentemente cair comece deixando elevamos escuta fenece findo fraqueza gente gratidão graças honra impolutas infinito jubilemos juntas levantemos meia novo olhos orando pedimos podermos pátria raiar servir som suave supriste torna vindo vozes"),
    (480, "Fim do Ano", "aleluias algo ame andando ano apetecido aproximou auxilia encurtou exaltado existência faltar famílias favores faze fenecido fim geração graças horas humana igreja lento louvores passar presença proteges segundo sirva susterá séculos tempo visitando voar"),
    (481, "Cristo e Sua Humilhação", "achar adoração aleluias aves belém cabeça covas cravaram deixaste descer dirá donde excelso foste furor hinos humilde humilhação lugar nascer ninhos num ouvirá pousar presépio puderam quiseste raposas rendendo teve trazendo vier vieste ódio"),
    (482, "Comunhão", "abençoaste aliança anime ato celebrar celebrarmos cercamos chamamos chamou comei comunhão cálice deve dever encha encher exemplo fazei humildade infinito lavando memorial memória mesa paracleto partiste preside queremos quiseste reinar ternura tomai união vezes"),
    (483, "Ora Vem Jesus", "arrebatar bradamos buscai comigo coroa darei disse empenho esperamos estamos firmes galardão gloriosa igreja lenho levarei lugar opróbrio ora oração possa preparar presto pro remidos sedentos trago velando vigiai"),
    (484, "Meus Pecados Levou", "amável anelo caminho condenação constante converte crimes desprezos divinal exemplo houve igual inda indigno infiel lavou levou livre marcou meigo morrer morreu mudou paciência pecados quis salvou sofreu sublime terno trevas verteu vil viver"),
    (485, "Andando Para o Céu", "alegre alegria andando cantarei crente desejo entrará estará feliz gozo mansão minh morte ouro pátria reina ruas santos satisfeito sião stou terá veraz"),
    (486, "Vasos Transbordantes", "abundante alegrarás altar brasas bênçãos cessar constantemente conter deixa descer deserto encher espalhar florescer fogo governar irão poderá possa precisa põe receber receberás ribeiro sacrifício stá transbordantes transbordar vaso vasos vazio vazios verás água"),
    (487, "Doxologia", "amado canto dada doxologia entoamos grande libertado nome onipotente onipresente onisciente ressuscitado seja trino"),
    (488, "O Áureo Dia", "alegrarão chegarão china congregados conquistou dentre derem derramando dia encherá entregou espalhemos estarmos estarão ganhou gloriosa juntos mensagem milhões nações povos purifica purificados purificou ralar redil salvos subirão tribos triunfantes virem áfrica áureo índia"),
    (489, "Chegai Para Adorar", "adorar anunciar atrás belém chegai deitado diante entoam estrelas hosanas incenso judá leito louvai magos messias mirra nasce nasceu oriente palhas pastorzinhos podemos portal presentes presépio prostram ricos rústico seguindo templo teto tributo universo"),
    (490, "Passando Está", "amoroso braços chama chamando confiando demorando demorar estende faminto fartar fatigado lançar mão ofertando oprimido passa passando pecador pão receber tomar"),
    (491, "Há Poder no Sangue de Jesus", "abandonar andar anjos bom caminhar confia consagração curar deixar força ganhar lealdade levar mensagem neste paralítico pecado pureza queres sangue vigor vitória vícios"),
    (492, "Jesus Virá do Céu", "achas anunciar brancas breve clareando comprado conduzirá cumprir demores depressa descansar desejas evangelho herança inteiro iremos mensageiros noiva penhor presto prometeu quis reino remido resgatar revela selado soará stou stão subindo trombeta vestes virá"),
    (493, "Ao Pai Voltai", "alvo ansioso chorais deixai ditoso enfim escolhei for glorioso gozo lar morar mui paterno recuseis regressei salvação salvo sereis tereis tomai trilho vero voltai"),
    (494, "Jerusalém Celestial", "ais belas cantarei celestial cidade contemplarei cristal cuja curar divinal fervor fez filhos gratidão imortal jaspe jerusálem maldição mansão mui muro noite passaram pranto raiou redor resplendor rio servirão sol verei vigor água árvores"),
    (495, "Cristo à Porta Está", "abre abrires bate entrar juízo libertar ouvires pecador porta triste voltará"),
    (496, "Jesus me Tirou da Lama", "andar canto clamado crendo desejo dum esperança fama fervor firmarei firmou fora fruir gloriosa horror horrível jazia lago lama lavei libertei novo num prazer proclamarei pôs rocha salvou seguir sentir servir soou tirou valor"),
    (497, "Meu Bom Salvador", "andando bom buscar conduz contemplo deu disse débil encheu encontro glorioso gozar gozo louvo lugar mirar morrendo morte mui pendurado precioso quis reino rosto salvar senda vagar vigor virá"),
    (498, "Guia-me ó Salvador", "amar corrupção deixes forte fruir gozo guia horrendo lado lar leva mar morrer neste perenal querido redentor salvaste salvação senda serei servir temor terrível vencedor viver"),
    (499, "A Santa Bíblia", "aflição altos alumias bíblia cessar conténs céus dentre dizes donde ensinas exortas falar fontes guias indigno lei letra lindos mortos mostras pecar pés reinarei repreendes tesouro triunfar vigor vim voz"),
    (500, "Quero ver a Jesus Cristo", "angelical anjos arcanjos bondoso conduzindo coro desejada eternamente face glórias gozar habitar hastes louvarei mensageiro mestre morada morar nessa obra precioso preparar pátria redentora redimidas redimido reina reino remidos reserva sofreu sublime trono viverei"),
    (501, "Vencendo Com o Bom Capitão", "armas bom capitão combater confessar conservar contra céus desanimar eficaz espada eternal fervor galardão guiar lutará nada pelejar poderá provação puro queiras serve tentador tentação terá tirar tudo vence vencendo vencer vencerá vier"),
    (502, "Ó Pastor Bendito", "amado brando buscamos busque contemple cordeirinhos cordeiros dado despertar escuta esperamos faze filhos graças luta manhã mil mãos noite nova oração pastor pequeninos pão rei repousar reverentes soberano sono unção vestir"),
    (503, "Vidas Consagradas ao Trabalho", "apresentam brancos busca cairão campos cativos cheias consagradas contritas desfrutareis douradas falem firmadas futuros infinita lábios maduros messes mostre mostrem necessita ordena pedem proclamem prontidão puros santas sega trabalhar trabalho transgressores trigais vidas voltarem"),
    (504, "Momento Solene", "achar alcança alcançar ano atrás bendita bens ciência corre débil efêmera eternidade existência expirando fama fica firme flor humano imortalidade império insondável momento morre mísero néscio passará pensamento plena presto resta solene sopro tempo"),
    (505, "As Palavras de Jesus", "afastam alentará anelo banquete belém cear conhecer crer dirá ditos ensinam festim fonte guiam haverá horror humilhado infundem instrução males mansidão maná mestre nelas ouvir palavras pobre provas tempo tenha trazem turbar vigor voz"),
    (506, "Bíblia Sagrada", "bendita bíblia calma cheia dela dom enriquece fortalece gloriosa infinita inteiro jóia mandada minh mostra nela obtenho ouço preciosa revela sagrada salvação sumo tesouro tocha torna verdadeiro verá voz"),
    (507, "Jesus Salva", "ama chama chorando céus demora dom entregar entregas gloriosa logo pecador recebe receber rei salva salvar salvação sumo tardar voz"),
    (508, "Sua Palavra Revelada", "atribulada beber belo calma caudal cesse clama dando dará donde dor duelo entrega explícita faze fim gran justa lei libertando mui olha palavra pecador pura redentor revelada sabor temor tristes ventura"),
    (509, "Ao Passar o Jordão", "adorarmos alcançará areia contemplarmos coroado entrarmos gloriosa gozo haverá jordão justiça mar margem morte passar passarmos praia profundo prometida prostrado pés remidos rio salvo salvos saudarem sentirá tantos unidos veremos verá virmos vista"),
    (510, "A Riqueza Divinal", "capas coxo crê curar defluxão dentes despertou divinal doença falhou febre gozareis gripe lesões maravilhas mudo nervos ouvirás pele pulmões rendemos rins riqueza sara sarar sarareis sarou sofreis surdo tirai tosse vais vereis visão"),
    (511, "Glorioso Deus", "acharei aleluias cantarei chegarão comigo conselheiro conter contigo contra estarei estarás ficarei firmados glorioso golpe gozar grato grei iluminará lar longe mister peregrino pesar possa preparou revés satisfaz satisfeitos sinto stou stás tribulação vindo"),
    (512, "O Amor Inesgotável", "andou angústias anos atinge brilhou brotava cegos comparável deixou eficaz fanal ideal igual imensa imenso implantar incomparável inefável inesgotável marca misericórdia olhos passem precioso procurou pujante pôs rico rio sanando sublime terá verá vitorioso"),
    (513, "Minha Alma Quer Ter", "além atroz bom choro consolar contigo céus daqui descanso desejo deste lar leva libertar longe minh morar nada ora par partir prazer preparaste pátria rei satisfaz sentirei sinto sofrimento"),
    (514, "Em Glória Esplendente", "aceita acender bodas calma começando demores dia enganado esplendente ires irá jubilar luzente lâmpada madeiro mentira noite nuvem orando parte perece perfeita pronta purificador temendo tomar verteu veste vestes vez vicio vinda virá voltar"),
    (515, "Se Cristo Comigo Vai", "andar boas comigo confiando contar contente desejo deserto dilação dura encontro falo fiel for gloriosa grato habitar irei levando levar lidarei mandar novas obedecer palavra par peregrino seguindo serei servir sorte temerei vales vencerei"),
    (516, "Cristo Meu Vero Amigo", "achei amigo antes cessou concederá conhecia culpas dará desejava estou fonte gozo levou libertou mensagem minh pecados perdoou plena poderoso proclamar promessas pronto purificação temor trabalhar transformou vero vigor vinhas vitória viva vivia"),
    (517, "Cura Divina", "cravou crendo crer creres crê cura curar dito doenças enfim fraco hei hás inda irás manando manifestar mui par poderoso podes puderes receber sarar virtude"),
    (518, "Salva-Vidas", "aceita afoga afundar antes bom cansa céus demorar desapareça desça horrível joga lançado lançar mar morte nada náufrago ondas orando pecador pecados perece pobre profundezas queres salva salvar segura sorte stá triste vidas"),
    (519, "Achei Jesus, Meu Salvador", "achei achou aflito amou braço cantando cessarei chamou cheguei consolação divinal dura escravidão estou fiel forte gratidão guardar morte mão perfeita real resgatou rocha salvação salvo seguro sustém tentação traz vencendo veraz vicio"),
    (520, "A Doce e Preciosa Voz", "achei alegre belo confiar conforto curar curou defensor ditoso doce dor esperança estado exortanto exulto feliz fim guia havia hora lembrar luta nele num olhou ouvi ouvia preciosa prevendo recebia soar testifico tristeza voz"),
    (521, "Vem o Passo Dar!", "alto contra culpas deixa deu entregar estou fez fonte hesitação lavar limpar limpo nele oferta passo pecado perdoar purificar refugiar salvar salvação salvou sangue temores toma trevas"),
    (522, "Rei da Glória", "adoração além aquel cabalmente chagas confessa confia conhecer crer declaram elevado eternamente excelsa ganhando morte multidão num onipotente penhor provam quão real recebeu rei reina reinando remida renascer rompeu sepultura sofreu subindo véu êxtase"),
    (523, "Cristo, a Fonte Escondida", "abriu alegrar beber cisternas conter correrá cujas dinheiro escondida esgotará estancar fartar fonte fontes gastaram homens imundos manará milhares muitas muitos nelas poços qualquer quiserem repletas roteiro sairá sede supremo venham vivas água águas"),
    (524, "Cristo Pensa em Mim", "abrigo almejo através ausentar calamidade conforto consola consolar desejo encontro estou excelsa fim força hei inimigo medo nisto ousadia pensa perigo provaste qualquer receio satisfeito separar temor tempestade tendo tudo verdade"),
    (525, "Vencendo Vem Jesus", "batalha clarim conquistou demonstrou descerá encarar entronizado frente furor governará grandes irá irão juiz julgar leis mostram multidões nações nuvens pequenos refulge refulgente regerá reinos reis retirada seguirão sinais soou triunfantes vencendo venceu vez"),
    (526, "Grandioso És Tu", "afirmo aima brilhar canta cintilantes contemplar contemplo criação cruento deixou distantes estrelado estrelas florestas ganhaste glórias grandioso imensa jubilando lenho maravilhado murmurando olho penso perfeição plantaste poupaste recordo relembro transborda vento vier vivido voltando"),
    (527, "Dominador É Deus", "abençoa aflição amar bom cessar confiar criou céus devemos ditou dominador duvideis esperai falharão filhos mananciais mão nele par potente promessas reina santos seres tempestade traz vontade"),
    (528, "Eu Te Amo, Ó Deus", "almejo amo desceu dor fruir lugar morreu morte prazer provaste sofrendo sucumbir temo"),
    (529, "Em Sua Graça", "belém maravilha morreu rico veio"),
    (530, "Vivifica a Tua Igreja", "almas ficará igreja murcha vigor vivifica"),
    (531, "Nome Precioso", "aceito aclamarás adorável alcance amado aparecer arma bom conforto contigo defender doce esperança for gozo leva nome perdão porvir precioso rei reis sendo terás traz"),
    (532, "Santo Nome", "doce melodia nome produz"),
    (533, "Honras Sejam ao Cordeiro", "adoramos amou cordeiro culto céus demos deu digno gratos honras morreu padeceu penou sejam sofredor triunfou vencedor"),
    (534, "Cristo É Real Pra Mim", "real vive"),
    (535, "Tu És Fiel Senhor", "ares brilhar bênçãos criaste darás desfrutarei dia eras esperança estrelas faltaste favor fiel filhos flores frutos guarda guias louvar lua mares mercê momento montanhas mudaste pleno porvir rico segurança serás sol sustenta tal universo"),
    (536, "Amigo Sem Igual", "amigo confiar convida falhará fim grande igual imenso lugar morreu mudará nele pecador perto salvar"),
    (537, "Sempre Comigo", "amar comigo cuida guarda protege seja trevas"),
    (538, "Tu, Senhor, És Nosso Amigo", "amado amigo guardar salvar vieste vives"),
    (539, "Ao Pensar na Dor Crucial", "amarei amplidão bom capaz coisas conter crucial destas deste destes dor enfim estarei extensão fim gloriar igual irei jorrar manancial mundanal mãos nesta neste pecador pensar prazer próprio pés rei sofrer suportou vil vãs"),
    (540, "Ao Ver a Cruz", "angustia compreendo conduzir derramam deseja dor ferida fronte graças irá mil morrer mão mãos orgulho pecador porvir provado pés rude salvação sangue sustar valor"),
    (541, "Calvário, Revelação de Amor", "abandono abandonou amou calvário compadeceu contemplamos deu dor grande meigo mistério morrendo oculto ofereceu olhou perdão revelação revelou sofrendo"),
    (542, "História de Cristo", "afrontas chora chorou consigo conta convencido convidou cruéis duras encarnando endurecidos escutou estendidas grava história inaudita indignos inimigos ladrão lembrou levantado mansamente moribundo mudança orgulhosa prontamente rebelde recusar rejeitou resistem revelar rogou seguem ímpios"),
    (543, "Cristo, Meu redentor", "bom morreste pastor redentor sangue verteste"),
    (544, "Creio, Senhor", "além cobrir creio dada desfrutarão entrar glorioso grande imortais lar pecador perdição perdão pobre redenção resgatou retidão sangue véu"),
    (545, "Porque Ele Vive", "amado amanhã chegar crer enfim enfrentarei enviou hora irei medo morreu morte mãos pecado perdoar ressurgiu salvar temor terei vitória vive vivo"),
    (546, "Manhã da Ressurreição", "alvor atroz contemplar dor enfim feliz manhã morte prazer queridos remidos ressurreição ressuscitar seduz supremo terão venturoso voltar"),
    (547, "O Rei Está Voltando", "abrindo aleluias aparece bons carreira ceifeiros cessou colheita completou desses encontro entoar festa findou indo labor muitas noticia ouvimos parte pregação rei remidos soando som subindo templo terminaram trabalho trasladados trasladar trombeta voltando voltou"),
    (548, "Breve Jesus Há de Vir", "breve buscar chegar devo lar pronto"),
    (549, "Ora Vem, Senhor Jesus", "aflições aguarda alvor ansiosos converteu corações desfazer dor igreja ora reino retardes suplicar tardar"),
    (550, "Breve Ele Volta", "breve vez virá volta"),
    (551, "O Santo Espírito", "anunciarmos consolador encheu plena salvação unção"),
    (552, "Quando para o Céu Nós Formos", "abrem atração belo canta chegarmos cheios compaixão crer daremos depressa eia estrada eternal finda formos galardão gloriosos hosanas júbilo leais num nuvens peregrinos portais portanto porvir relance saudar seja servir sombras toldam tranqüilo véu"),
    (553, "Oh! Pai, o Santo Espírito", "aflições ampare console convença conversão corações dor habite meio opere outorgar pedimos redenção sermos templos"),
    (554, "O Evangelho", "confiar evangelho grande levar morrer nele salvo veio viver"),
    (555, "O Redentor", "desfaz dor favor firme gozo hosanas interceder livra lutas minorando morreu nele redentor reina resguardar salvo sustentar temor tristeza valer vive vivo"),
    (556, "Lê a Bíblia", "alcançar alimentar almejas bíblia caminhar conhecer dele desejas enriquecer exultar fervor habitar junto mensagem nela pleno pretendes promessas proteção queres redimida rico usufruir verdade"),
    (557, "A Palavra da Vida", "abre alegria alento almas aprendemos belos brilhe bíblia comunhão concede conceder céus desfrutamos engano ensino entoando erros esclarece estudo exultemos faze frutos ilumina instrução leitura livra livro manifesta mortos palavra produz reviver tendo vivifica"),
    (558, "Daí-me a Bíblia", "andar anelo anunciar bom bíblia caminho certo conduzam conduzem dai dela doutrina ensinos farol fonte glorioso grata guia livrar livro nesta nova palavras pecado poderosas precioso preciso renovar roteiro seja veio"),
    (559, "Bíblia Sagrada", "atalaia brasil brilhante bíblia carta corrução dedos desta enviada espada falar flor fulgor habitar jangada jardim jornada jóia lança levam linda livro lábios mapa mostra palavra radiante rejeitada sagrada saiu seguem varonil velas vituperador"),
